(window.CHI_DATA = window.CHI_DATA || []).push({"id": "chi-4", "subject": "國文", "chapter": "第四課", "title": "愛蓮說", "total": 142, "levels": {"必考": 15, "常考": 8}, "secs": {"題解": "作者與文體", "字詞": "字音字形・字義詞性", "賞析": "主旨・結構・修辭", "延伸": "成語・花木・閱讀"}, "mapname": {}, "concepts": [{"id": "k5", "name": "蓮花七德與君子之德", "n": 29, "level": "必考", "sec": "賞析", "card": {"說明": "作者以蓮花生長及形態的七個面向，具體對應儒家君子的內外德行修養。從生存環境的自愛，到言行胸襟的坦蕩端正，再到令人生敬的人格尊嚴，層層構建理想君子的標準。", "關鍵名詞": "<div class=\"kv\"><b>出淤泥而不染</b>：潔身自愛，不同流合污。</div><div class=\"kv\"><b>濯清漣而不妖</b>：節操高雅，不逢迎媚世。</div><div class=\"kv\"><b>中通外直</b>：胸懷坦蕩，行為正直。</div><div class=\"kv\"><b>不蔓不枝</b>：不攀附權貴，不結黨營私。</div><div class=\"kv\"><b>香遠益清</b>：品格高潔，美名遠播。</div><div class=\"kv\"><b>亭亭淨植</b>：獨立挺拔，端莊不群。</div><div class=\"kv\"><b>可遠觀而不可褻玩焉</b>：人格莊重，令人敬重而不敢輕慢。</div><div class=\"kv\">注意：七德講的都是個人修養，沒有「博施濟眾，仁民愛物」；課文也沒寫蓮的顏色。</div>", "因果／影響": "使蓮花成為千百年來「高尚情操、潔身自愛」的代名詞，確立儒家士人處於混亂污濁環境中仍秉持道德節操的行為圭臬。", "出處": "自修第<span class=\"tcy\">98</span>、102、104頁／講義第<span class=\"tcy\">68</span>、<span class=\"tcy\">71</span>頁。", "標示": "自修與講義皆列為「絕對必考／重點」。"}, "imgs": [], "clusters": [{"t": "七德對應", "n": 17, "ids": ["c4-47", "c4-48", "c4-50", "c4-51", "c4-57", "c4-69", "c4-87", "c4-88", "c4-89", "c4-92", "c4-93", "c4-106", "c4-122", "c4-127", "c4-130", "c4-134", "c4-138"]}, {"t": "君子之德", "n": 6, "ids": ["c4-18", "c4-21", "c4-26", "c4-85", "c4-99", "c4-115"]}, {"t": "文句運用", "n": 2, "ids": ["c4-28", "c4-67"]}, {"t": "人物對應", "n": 2, "ids": ["c4-96", "c4-139"]}, {"t": "蓮的描寫", "n": 1, "ids": ["c4-81"]}, {"t": "閱讀理解", "n": 1, "ids": ["c4-100"]}]}, {"id": "k12", "name": "延伸閱讀與文意理解", "n": 25, "level": "必考", "sec": "延伸", "card": {"說明": "延伸閱讀題會給一段課外文字或新詩，考主旨、文意對應或詠物對象。做法：先圈出關鍵句（因果、轉折、結論），再回到選項逐字比對；詠物題則抓季節、顏色、習性。", "關鍵名詞": "<div class=\"kv\"><b>文意對應</b>：題目給一段話，問最接近哪句成語或論語——先用自己的話把重點說一次再去找。</div><div class=\"kv\"><b>用字精簡</b>：找意思重複的詞（如「吝惜」與「捨不得」、「不然」與「否則」）。</div><div class=\"kv\"><b>圖表題</b>：先看表頭有幾個項目，再一個一個核對選項。</div>", "因果／影響": "選項中出現「都」「皆」「一定」等絕對字眼時，常是錯誤選項。", "出處": "自修第107～112頁／講義第<span class=\"tcy\">75</span>～<span class=\"tcy\">77</span>頁", "標示": "考卷每回都有 <span class=\"tcy\">2</span>～<span class=\"tcy\">4</span> 題"}, "imgs": [], "clusters": [{"t": "文意理解", "n": 11, "ids": ["c4-9", "c4-12", "c4-31", "c4-32", "c4-59", "c4-60", "c4-63", "c4-65", "c4-98", "c4-131", "c4-132"]}, {"t": "閱讀理解", "n": 4, "ids": ["c4-14", "c4-19", "c4-29", "c4-58"]}, {"t": "新詩判讀", "n": 4, "ids": ["c4-30", "c4-94", "c4-95", "c4-136"]}, {"t": "圖表判讀", "n": 2, "ids": ["c4-27", "c4-73"]}, {"t": "用字精簡", "n": 2, "ids": ["c4-36", "c4-123"]}, {"t": "詩歌賞析", "n": 1, "ids": ["c4-74"]}, {"t": "謎語判讀", "n": 1, "ids": ["c4-101"]}]}, {"id": "k11", "name": "成語・花木意象・人物", "n": 22, "level": "必考", "sec": "延伸", "card": {"說明": "考卷常延伸考與花、植物有關的成語與意象：<b>菊</b>＝隱逸（陶淵明）、<b>蓮</b>＝君子（周敦頤）、<b>牡丹</b>＝富貴（百花王）、<b>梅</b>＝堅貞（林逋，梅妻鶴子）、<b>竹</b>＝虛心、有節（蘇軾）、<b>松柏</b>＝堅毅、<b>柳</b>＝離別、<b>蘭</b>＝高潔（屈原）、<b>紅豆</b>＝相思、<b>油桐花</b>＝五月雪。", "關鍵名詞": "<div class=\"kv\"><b>蓮的成語</b>：蓮開並蒂（夫妻恩愛、好事成雙）、步步蓮花（女子步態輕盈）、舌粲蓮花（口才好）、出水芙蓉（清新自然）、藕斷絲連（關係沒斷乾淨）。</div><div class=\"kv\"><b>褒貶</b>：蕙質蘭心、松柏後凋、胸有成竹（褒）；水性楊花、明日黃花、紅杏出牆、花言巧語（貶）。</div>", "因果／影響": "成語題先想「原本的意思」，再看句子裡的情境對不對得上；不要只看字面有「蓮」「花」就選。", "出處": "自修第108、111、112頁／講義第<span class=\"tcy\">75</span>、<span class=\"tcy\">76</span>頁", "標示": "講義標為「延伸補充」"}, "imgs": [], "clusters": [{"t": "成語運用", "n": 5, "ids": ["c4-16", "c4-39", "c4-40", "c4-77", "c4-109"]}, {"t": "花木意象", "n": 5, "ids": ["c4-61", "c4-62", "c4-64", "c4-71", "c4-114"]}, {"t": "詞語運用", "n": 4, "ids": ["c4-4", "c4-8", "c4-43", "c4-118"]}, {"t": "人物與花木", "n": 4, "ids": ["c4-10", "c4-15", "c4-54", "c4-66"]}, {"t": "詠花詩", "n": 3, "ids": ["c4-25", "c4-97", "c4-119"]}, {"t": "成語褒貶", "n": 1, "ids": ["c4-126"]}]}, {"id": "k6", "name": "三種人格與末段三嘆", "n": 15, "level": "必考", "sec": "賞析", "card": {"說明": "作者以菊、牡丹、蓮代表三種截然不同的人生態度與處世抉擇 <span class=\"tcy\">3</span>, <span class=\"tcy\">8</span>, <span class=\"tcy\">16</span>：菊花是「隱逸者」，追求潔身自好但逃避現實，屬消極出世的「獨善其身」；牡丹是「富貴者」，汲汲營營於功名利祿，屬同流合污的「逐利求名」；蓮花是「君子者」，雖處濁世而不改操守，具備不孤傲、不逢迎、積極入世的「兼善天下」抱負。", "關鍵名詞": "君子人格（兼具高潔道德操守與入世情懷，潔身自愛、守正不阿的理想人格）。", "因果／影響": "引導讀者反思自身價值觀，作者藉「同予者何人」感嘆具有道德理想之同道極少，寄託孤傲堅持與深沉感慨。", "出處": "自修第<span class=\"tcy\">98</span>、102頁／講義第<span class=\"tcy\">68</span>頁。", "標示": "自修標為「要句批判／重點」；講義標為「章法分析／必考」。"}, "imgs": [], "clusters": [{"t": "末段涵義", "n": 9, "ids": ["c4-13", "c4-23", "c4-49", "c4-55", "c4-82", "c4-90", "c4-117", "c4-125", "c4-141"]}, {"t": "三花人格", "n": 4, "ids": ["c4-7", "c4-56", "c4-91", "c4-121"]}, {"t": "作者態度", "n": 2, "ids": ["c4-22", "c4-116"]}]}, {"id": "k9", "name": "一字多義與詞性", "n": 14, "level": "常考", "sec": "字詞", "card": {"說明": "一字多義：<b>益</b>（香遠益清＝更加／延年益壽＝增加）、<b>宜</b>（宜乎眾矣＝應當）、<b>焉</b>（褻玩焉＝句末語氣詞／心不在焉＝在這裡）、<b>之</b>（草木之花＝的／蓮之愛＝提賓助詞／求之不得＝代詞）、<b>而</b>（出淤泥而不染＝卻，轉折／學而時習之＝並且）。", "關鍵名詞": "<div class=\"kv\"><b>副詞</b>：修飾動詞或形容詞、表示程度，如「盛」愛（非常）、「益」清（更加）、「甚」蕃（很）、「鮮」有聞（少）。</div><div class=\"kv\"><b>名詞轉動詞</b>：不蔓不「枝」——在「不」後面的名詞「蔓」「枝」轉成動詞（生出藤蔓、長出枝節）。</div><div class=\"kv\"><b>人稱代詞</b>：第一人稱 予、余、吾；第二人稱 爾、君、汝；第三人稱 伊、其、之。</div>", "因果／影響": "字義題的做法：把字放回原句翻譯一次，再比較兩邊的意思；詞性題則看它在句子裡是在「做動作」「形容」還是「修飾動作的程度」。", "出處": "自修第<span class=\"tcy\">99</span>、100頁／講義第<span class=\"tcy\">69</span>頁", "標示": "自修與講義皆標為「常考／易錯」"}, "imgs": [], "clusters": [{"t": "字義比較", "n": 6, "ids": ["c4-2", "c4-33", "c4-37", "c4-83", "c4-107", "c4-137"]}, {"t": "詞性判斷", "n": 5, "ids": ["c4-3", "c4-44", "c4-76", "c4-113", "c4-129"]}, {"t": "而的用法", "n": 1, "ids": ["c4-38"]}, {"t": "通同字", "n": 1, "ids": ["c4-105"]}, {"t": "人稱代詞", "n": 1, "ids": ["c4-133"]}]}, {"id": "k8", "name": "字音字形", "n": 12, "level": "常考", "sec": "字詞", "card": {"說明": "本課常考的字音、字形：「蕃」通「繁」（多）；「鮮」讀ㄒㄧㄢˇ（少）；「褻」讀ㄒㄧㄝˋ（輕慢）；「濯」讀ㄓㄨㄛˊ（洗）；「盛」讀ㄕㄥˋ（非常）；「予」讀ㄩˊ（我）。考卷最常拿形近字、同音字來比：濯／擢、淤積／淤塞、蔓（藤蔓）／漫（漫不經心）、褻（褻玩）／屑（不屑）。", "關鍵名詞": "<div class=\"kv\"><b>破音字</b>：同一個字因意思不同而讀音不同，如「鮮」ㄒㄧㄢ（新鮮）／ㄒㄧㄢˇ（少）、「盛」ㄕㄥˋ（盛愛）／ㄔㄥˊ（盛飯）、「予」ㄩˊ（我）／ㄩˇ（給予）。</div><div class=\"kv\"><b>通同字</b>：古書借用音同或音近的字，如「蕃」通「繁」。</div>", "出處": "自修第<span class=\"tcy\">99</span>、100頁／講義第<span class=\"tcy\">66</span>、<span class=\"tcy\">69</span>頁", "標示": "自修標為「字形字音辨正／必考」；講義標為「形音義大會通」", "因果／影響": "字形題的做法：先把每一組注音都寫成國字，再逐一比對；字音題則先判斷字義，字義不同時讀音常常也不同。"}, "imgs": [], "clusters": [{"t": "字形辨識", "n": 6, "ids": ["c4-1", "c4-35", "c4-75", "c4-79", "c4-104", "c4-128"]}, {"t": "字音辨識", "n": 6, "ids": ["c4-5", "c4-24", "c4-34", "c4-78", "c4-103", "c4-124"]}]}, {"id": "k10", "name": "修辭與句型", "n": 11, "level": "常考", "sec": "賞析", "card": {"說明": "本課常考的修辭：<b>譬喻</b>（菊，花之隱逸者也＝把花比作人，暗喻）、<b>排比</b>與<b>類疊</b>（三句「○，花之○○者也」）、<b>映襯</b>（菊少、蓮更少、牡丹多的對照）、<b>激問</b>（同予者何人？＝沒有幾個人）、<b>象徵</b>（蓮象徵君子）。考卷也常延伸考雙關、借代、判斷句。", "關鍵名詞": "<div class=\"kv\"><b>激問</b>：問句的答案就在問題的反面。</div><div class=\"kv\"><b>映襯</b>：把兩種相反的事物放在一起比較，凸顯重點。</div><div class=\"kv\"><b>諧音雙關</b>：利用同音字表達兩層意思，如蓮子＝憐子、絲＝思、魚＝餘。</div><div class=\"kv\"><b>判斷句</b>：「A，B 也」「A 是 B」，如「蓮，花之君子者也」。</div>", "因果／影響": "辨識修辭時，先看「句子長相」（排比、類疊、判斷句），再看「意思」（譬喻、映襯、激問）。", "出處": "自修第101、102、109、112頁／講義第<span class=\"tcy\">70</span>頁", "標示": "自修標為「修辭辨析／常考」"}, "imgs": [], "clusters": [{"t": "譬喻", "n": 2, "ids": ["c4-17", "c4-80"]}, {"t": "排比譬喻", "n": 2, "ids": ["c4-41", "c4-112"]}, {"t": "激問", "n": 1, "ids": ["c4-42"]}, {"t": "反語", "n": 1, "ids": ["c4-46"]}, {"t": "映襯", "n": 1, "ids": ["c4-68"]}, {"t": "雙關", "n": 1, "ids": ["c4-72"]}, {"t": "借代", "n": 1, "ids": ["c4-110"]}, {"t": "象徵", "n": 1, "ids": ["c4-120"]}, {"t": "句型", "n": 1, "ids": ["c4-140"]}]}, {"id": "k3", "name": "托物言志（藉物抒懷）", "n": 4, "level": "一般", "sec": "賞析", "card": {"說明": "本篇為藉物抒懷（托物言志）的散文典範，表面寫花，實則寫人。作者藉由描繪蓮花的生長環境、外觀形貌與香氣特質，將自然物的人格化，生動具象地象徵君子的高尚美德。全文將蓮、君子、作者三者融為一體，達到物我交融的藝術境界。", "關鍵名詞": "托物言志（藉由對特定具體事物的描繪，寄託作者個人的品格、胸懷、志向或道德追求的寫作手法）。", "因果／影響": "將抽象深奧的道德修養具象化為可親可感的蓮花形象，使立意深刻、言簡意賅，發人省思。", "出處": "自修第<span class=\"tcy\">95</span>、<span class=\"tcy\">98</span>、101頁／講義第<span class=\"tcy\">65</span>、<span class=\"tcy\">68</span>、<span class=\"tcy\">70</span>頁。", "標示": "自修標為「學習重點／必考」；講義標為「讀後檢測站／重點」。"}, "imgs": [], "clusters": [{"t": "托物言志", "n": 2, "ids": ["c4-70", "c4-102"]}, {"t": "寫作目的", "n": 1, "ids": ["c4-53"]}, {"t": "課文比較", "n": 1, "ids": ["c4-142"]}]}, {"id": "k7", "name": "倒裝句：賓語提前", "n": 4, "level": "一般", "sec": "字詞", "card": {"說明": "文章結尾處的「菊之愛」、「牡丹之愛」、「蓮之愛」，並非一般的偏正結構（名詞修飾名詞），而是文言文常見的倒裝句型。正常語序應為「愛菊」、「愛牡丹」、「愛蓮」。在此句型中，「之」字為助詞，專門用來將受詞（賓語）提前以示強調，本身毫無意義。", "關鍵名詞": "提賓助詞（在文言賓語前置句中起結構指示作用、無實際意義的助詞）。", "因果／影響": "形成整齊凝鍊的句式節奏，更加強了被提前事物的焦點感與感嘆語氣。", "出處": "自修第<span class=\"tcy\">97</span>、<span class=\"tcy\">99</span>、102、109頁／講義第<span class=\"tcy\">67</span>、<span class=\"tcy\">69</span>頁。", "標示": "自修與講義皆標為「常考／易錯」。"}, "imgs": [], "clusters": [{"t": "賓語提前", "n": 4, "ids": ["c4-11", "c4-45", "c4-52", "c4-108"]}]}, {"id": "k4", "name": "襯托法：正襯與反襯", "n": 3, "level": "一般", "sec": "賞析", "card": {"說明": "文章先後點出陶淵明獨愛的「菊」、世人盛愛的「牡丹」，以及作者獨愛的「蓮」。作者運用「對比烘托」：以隱逸的「菊」作為「正襯／陪襯」，凸顯蓮花處濁世而能自守的高貴；以富貴世俗的「牡丹」作為「反襯」，批判趨炎附勢、貪慕富貴的世風。", "關鍵名詞": "襯托（利用事物之間相似或相反的特點，以次要事物陪襯主要事物的修辭手法，分為正襯與反襯）。", "因果／影響": "層次分明地形成「世俗之愛（反襯）與獨特之愛（正襯、主體）」兩兩對比，末段透過「一褒（菊）、一反詰（蓮）、一貶（牡丹）」結穴，加深批判世風與孤芳自持的感慨。", "出處": "自修第<span class=\"tcy\">98</span>、101、102、104頁／講義第<span class=\"tcy\">68</span>、<span class=\"tcy\">70</span>頁。", "標示": "自修與講義皆標為「重點／必考」。"}, "imgs": [], "clusters": [{"t": "主從結構", "n": 1, "ids": ["c4-20"]}, {"t": "寫作技巧", "n": 1, "ids": ["c4-84"]}, {"t": "襯托作用", "n": 1, "ids": ["c4-86"]}]}, {"id": "k1", "name": "文體常識：「說」體", "n": 2, "level": "一般", "sec": "題解", "card": {"說明": "「說」亦稱雜說，是古代用來解析事理、闡述己意的文體。「說」與偏重議論辨析的「論」較難以區隔，大體而言「說」偏重在說明事理，「論」偏重在議論辨析；因兩者性質相近，現代統稱為「論說文」。「說」這種文體在唐代與宋代之際開始興盛發展。", "關鍵名詞": "「說」（古代用來解析事理、闡述己意，偏重說明事理的文體，如韓愈《馬說》、周敦頤《愛蓮說》）。", "因果／影響": "作者藉由「說」體彈性夾敘夾議、藉物寓意的特質，達到「簡明扼要」抒發個人胸懷與志向的效果，而非長篇大論宣揚理論。", "出處": "自修第<span class=\"tcy\">95</span>頁／講義第<span class=\"tcy\">65</span>頁。", "標示": "自修標為「預習導覽」；講義標為「課文前哨站／重點」。"}, "imgs": [], "clusters": [{"t": "文體常識", "n": 2, "ids": ["c4-6", "c4-111"]}]}, {"id": "k2", "name": "作者：周敦頤（宋代理學之祖）", "n": 1, "level": "一般", "sec": "題解", "card": {"說明": "周敦頤，字茂叔，北宋道州營道人，世稱濂溪先生。他為官廉潔公正，晚年在廬山蓮花峰下築濂溪書堂講學，程顥、程頤皆為其門生。周敦頤思想兼納儒、道、釋三家，開創宋代理學先河，被尊為「宋代理學之祖」。", "關鍵名詞": "理學（宋代以周敦頤、程顥、程頤、朱熹等為代表的哲學思想，致力於闡釋義理、兼談性命）。", "因果／影響": "周敦頤開創濂溪學派，奠定宋代道統傳承之基礎，並以清廉拔俗的實際品格落實其思想追求。", "出處": "自修第<span class=\"tcy\">94</span>、<span class=\"tcy\">95</span>、115頁／講義第<span class=\"tcy\">65</span>頁。", "標示": "自修標為「學習焦點／重點」；講義標為「作者細說／重要」。"}, "imgs": [], "clusters": [{"t": "作者與文人", "n": 1, "ids": ["c4-135"]}]}], "questions": [{"id": "c4-1", "no": "1", "c": "k8", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的注音寫成國字後，何組字形相同？", "o": ["鳳「ㄈㄥˊ」／飛「 fly 」我詐", "「ㄆㄥˊ」氣凌人／「ㄆㄥˊ」蓽生輝", "「ㄔㄣˋ」心如意／「ㄔㄣˋ」托", "不「ㄐㄧˋ」不拔／荒煙「ㄐㄧˋ」草"], "a": 2, "e": "考點：同音字辨形。\n本題 (A) 選項轉檔時出錯，正在對照講義第 74 頁原題，暫以教用答案 (C) 為準。\n★ 字形題：先把每一組注音都寫成國字，再逐一比對字形是否相同。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "C"}, {"id": "c4-2", "no": "2", "c": "k9", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的字，何組意義相同？", "o": ["不可褻「玩」焉／「玩」物喪志", "香遠「益」清／精「益」求精", "不「蔓」不枝／伸長了藤「蔓」", "「中」通外直／「中」途離開"], "a": 1, "e": "考點：一字多義。\n(B) 香遠「益」清＝更加；精「益」求精＝更加 → 意義相同。\n(A) 褻「玩」＝玩弄、輕慢對待；「玩」物喪志＝玩賞、沉迷。\n(C) 不「蔓」＝（動詞）生出藤蔓；藤「蔓」＝（名詞）藤蔓。\n(D) 「中」通＝裡面；「中」途＝半路。\n★ 益：香遠益清、多多益善、精益求精 → 都是「更加」。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-3", "no": "3", "c": "k9", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的字，何者詞性與「不肯媚世隨俗」句中的「媚」字相同？", "o": ["中「通」外直，不蔓不枝", "「署」名", "諸事不「便」", "世人盛愛牡丹，「盛」"], "a": 2, "e": "考點：詞性判斷。「不肯媚世隨俗」的「媚」是動詞（討好）。\n本題選項轉檔時有缺漏，(C)「便」是形容詞，與「媚」詞性並不相同；(B)「署」名是動詞，看起來才和「媚」相同。請對照講義第 74 頁原題。\n★ 詞性題：把字放回句子，看它是在「做動作」（動詞）還是在「形容」（形容詞）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "C"}, {"id": "c4-4", "no": "4", "c": "k11", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "語文課上，老師要求同學以「亭亭」一詞造句，下列哪一位同學的表現能得到老師的稱讚？", "o": ["妙麗：隨著夏天到來，「亭亭」荷葉逐漸浮現水面", "榮恩：男孩子長大了，就該表現出「亭亭」玉立的風範", "哈利：河邊春草「亭亭」，恰如心中無限的離愁", "馬份：你「亭亭」再走，不要那麼著急"], "a": 0, "e": "考點：「亭亭」的用法——形容高聳挺立的樣子（課文：亭亭淨植）。\n(A) 荷葉亭亭浮出水面：用法正確。\n(B) 「亭亭玉立」形容女子身材修長美好，不用在男孩子身上。\n(C) 形容春草茂盛應用「萋萋」。\n(D) 「停停再走」才對，誤用同音字。\n★ 亭亭＝挺立；亭亭玉立＝女子身材修長。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-5", "no": "5", "c": "k8", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的字，哪一組讀音相同？", "o": ["「濯」清漣而不妖／「擢」髮難數", "「盛」愛牡丹／幫忙「盛」飯", "「予」獨愛蓮／給「予」幫助", "可「遠」觀而不可褻玩焉／親賢臣，「遠」小人"], "a": 0, "e": "考點：形近字讀音。\n(A) 「濯」ㄓㄨㄛˊ／「擢」ㄓㄨㄛˊ → 讀音相同。\n(B) 「盛」愛ㄕㄥˋ／「盛」飯ㄔㄥˊ。\n(C) 「予」獨愛蓮ㄩˊ（我）／給「予」ㄩˇ（給）。\n(D) 可「遠」觀ㄩㄢˇ／「遠」小人ㄩㄢˋ（疏遠，動詞）。\n★ 濯、擢、濯濯都讀ㄓㄨㄛˊ。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-6", "no": "6", "c": "k1", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有關愛蓮說中「說」的文體，下列說明何者正確？", "o": ["盛行於漢、魏之際", "是用來解析事理，闡述己意", "與偏重議論辨析的「論」性質殊異", "篇幅甚長，專門用以解釋歷史典故"], "a": 1, "e": "考點：「說」體。\n(B) 正確：「說」是用來解析事理、闡述己意的文體。\n(A) 錯：盛行於唐、宋。\n(C) 錯：與「論」性質相近，現代統稱論說文。\n(D) 錯：篇幅通常簡短，不是專門解釋典故。\n★ 說：唐宋盛行、說明事理、與論相近；代表作：馬說、愛蓮說。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-7", "no": "7", "c": "k6", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "關於愛蓮說一文中，周敦頤對「菊」和「蓮」的看法，下列敘述何者正確？", "o": ["菊像是花中的富貴之人，廣受歡迎", "菊具備出淤泥而不染的精神", "蓮生長在清水卻不顯妖媚，可見其高尚傲慢", "蓮處於俗世之中，卻不厭棄世俗，具備「兼善天下」的精神"], "a": 3, "e": "考點：菊與蓮的人格象徵。\n(D) 正確：蓮處濁世而潔身自愛，積極入世，有「兼善天下」的精神。\n(A) 錯：富貴者是牡丹。\n(B) 錯：出淤泥而不染是蓮。\n(C) 錯：不妖是「高潔、不媚俗」，不是傲慢。\n★ 菊＝隱逸（出世）；蓮＝君子（入世）；牡丹＝富貴（隨俗）。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-8", "no": "8", "c": "k11", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「青紅皂白」一詞中，「皂」原指黑色。「不分青紅皂白」意為不能辨別顏色，引申為人不辨是非曲直。下列「　」字原意因此有所轉變的詞語，何者仍表示真正的顏色？", "o": ["媽媽看到大雄考零分的考卷，霎時臉都「綠」了", "他犯錯在先，我們應當據理力爭並汲取新知，不能讓他自己當電腦「白」痴", "小夫和胖虎為了小事爭執，搞得雙方心中都有點「紅」耳赤", "幾次考試的挫敗，使他心「灰」意冷，從此對讀書失去了信心"], "a": 2, "e": "考點：顏色字的引申義。題目問「仍表示真正顏色」的。\n(C) 面紅耳赤：激動時臉真的變紅 → 仍是真正的顏色。\n(A) 臉都綠了：形容非常生氣、驚恐，不是真的變綠。\n(B) 白痴：「白」是沒有、空白，不是顏色。\n(D) 心灰意冷：「灰」是消沉，不是顏色。\n★ 判斷方法：問自己「真的看得到這個顏色嗎？」", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-9", "no": "9", "c": "k12", "src": "講義 第74頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「我向默默耕耘者學習等待，也向堅持不懈者學習勇敢……我從傲慢的人身上學會了謙遜，也從奢靡的人身上加以學習，學到了簡樸。」這段文字最能呼應論語中的哪一段話？", "o": ["學而時習之，不亦說乎", "人之過也，各於其黨。觀過，斯知仁矣", "三人行，必有我師焉。擇其善者而從之，其不善者而改之", "君子不重則不威，學則不固。主忠信。無友不如己者。過則勿憚改"], "a": 2, "e": "考點：文意對應論語。\n題文：向好的人學優點，從不好的人身上反省、學到相反的長處 → (C) 三人行，必有我師焉；擇其善者而從之，其不善者而改之。\n(A) 講學習的快樂；(B) 講從過錯看人的仁德；(D) 講君子要莊重、交友、改過。\n★ 「善者從之、不善者改之」＝好壞都能當老師。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-10", "no": "10", "c": "k11", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「不但草木，凡天下之物，皆是有情有理的，也和人一樣，得了知己，便極有靈驗的。」（紅樓夢）根據這段文句，下列各人物與其知己的配對，哪一項有誤？", "o": ["林逋—梅花", "陸羽—茶", "屈原—竹", "王羲之—鵝"], "a": 2, "e": "考點：古人與其「知己」之物（張潮幽夢影）。\n林逋—梅（梅妻鶴子）、陸羽—茶（茶聖）、王羲之—鵝 皆正確。\n(C) 錯：屈原的知己是「蘭」（香草美人）；愛竹的是蘇軾（寧可食無肉，不可居無竹）、王徽之。\n★ 菊—陶淵明、蓮—周敦頤、梅—林逋、蘭—屈原、竹—蘇軾、鵝—王羲之、茶—陸羽。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-11", "no": "11", "c": "k7", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列各選項的「唯」字，何者還原原句後，其位置與「唯利是圖」相同？", "o": ["唯利是圖", "主義是從", "牡丹之愛", "何難之有"], "a": 0, "e": "考點：賓語提前句型。「唯利是圖」＝唯圖利，「是」是提賓助詞，把賓語「利」提到動詞「圖」前面。\n本題選項轉檔時有誤（(A) 和題目相同），請對照講義第 75 頁原題。\n同類句型：唯命是從（唯從命）、馬首是瞻（唯瞻馬首）、牡丹之愛（愛牡丹）、何難之有（有何難）。\n★ 看到「唯……是……」「……之愛」，先還原成「動詞＋賓語」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "A"}, {"id": "c4-12", "no": "12", "c": "k12", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「人亦有所長，不可惡其人而忽其是；君子亦有所失，不可好其人而飾其非。」這句話的涵義，與下列何者最接近？", "o": ["小人好惡以己，君子好惡以道", "對待小人要迎合他的過錯，待君子要要求他的美德", "好君子而知其過，惡小人而知其美", "對待君子要嚴苛，待小人要寬容"], "a": 2, "e": "考點：文意理解。\n題文：不能因為討厭一個人就忽略他的優點；不能因為喜歡一個人就掩飾他的錯 → (C) 喜歡君子也要知道他的過錯，討厭小人也要知道他的長處。\n(A) 講好惡的標準；(B)(D) 對待方式錯誤。\n★ 關鍵：好惡分明，但要「客觀」看人。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-13", "no": "13", "c": "k6", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「菊之愛，陶後鮮有聞。蓮之愛，同予者何人？牡丹之愛，宜乎眾矣！」這段話主要是暗指何者？", "o": ["有道德理想的人很少", "一般大眾的品味不凡", "百花之王，牡丹當之無愧", "很多人喜歡見異思遷"], "a": 0, "e": "考點：末段三嘆的主旨。\n「同予者何人」感嘆像自己一樣愛蓮（追求君子之德）的人極少 → (A) 有道德理想的人很少。\n(B) 錯：牡丹之愛宜乎眾矣是委婉批評世俗。\n(C)(D) 與文意無關。\n★ 末段：菊（隱者少）、蓮（君子更少）、牡丹（追富貴者多）。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-14", "no": "14", "c": "k12", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「是莫笑箕也者，無一時一刻，不適耳目之觀；無一物一絲，不備家常之用者也。有五穀之實，而不得其名；兼藕與荷花之長，而各去其短。種種之利，有大於此者乎？」讀完這段文字，下列何者最符合作者的觀點？", "o": ["荷花在水生花卉中最為名貴，也最具欣賞價值", "藕絲具有極高經濟價值，種植作物無比此更大", "一年四季皆有盛開的、香氣逼人的荷花可觀賞", "荷花整株各部分皆有實用價值，具高度經濟價值"], "a": 3, "e": "考點：閱讀理解（李漁〈芙蕖〉）。\n文中說蓮「無一時一刻不適耳目之觀；無一物一絲不備家常之用」，又有「五穀之實」——整株從花、葉、藕到蓮子都有用 → (D)。\n(A) 文中沒比較名貴；(B) 不只藕絲；(C) 荷花不是四季開。\n★ 抓關鍵句：「種種之利」＝全株都實用。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-15", "no": "15", "c": "k11", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「舒伯特為人高風亮節，淡泊名利，可說是維也納的□□□。」根據上文文意推測，缺空處最適合填入的是下列何人？", "o": ["李商隱", "李太白", "陶淵明", "白居易"], "a": 2, "e": "考點：用人物來比喻。\n「高風亮節，淡泊名利」→ 不慕榮利的隱士 (C) 陶淵明。\n(A) 李商隱：晚唐詩人，以無題詩著稱。\n(B) 李白：浪漫詩仙。\n(D) 白居易：社會寫實詩人。\n★ 淡泊名利、歸隱田園 → 陶淵明。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-16", "no": "16", "c": "k11", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有關蓮的成語很多，下列何者是用來祝人好事成雙或夫妻恩愛的吉祥話？", "o": ["步步蓮花", "蓮開並蒂", "三寸金蓮", "舌粲蓮花"], "a": 1, "e": "考點：與「蓮」有關的成語。\n(B) 蓮開並蒂：一根莖上開兩朵花，比喻夫妻恩愛或好事成雙。\n(A) 步步蓮花：形容女子步態輕盈優美。\n(C) 三寸金蓮：古代女子纏足的小腳。\n(D) 舌粲蓮花：形容口才很好。\n★ 並蒂＝成雙。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-17", "no": "17", "c": "k10", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「牡丹，花之富貴者也」使用了「譬喻」修辭。下列何者與此相同？", "o": ["這飯確實是他們立的，這家確實是他們立的", "藉口是一種消除自怨自責的止痛劑", "人生什麼事最苦呢？", "不要怕，天塌下來，我幫你頂著"], "a": 1, "e": "考點：譬喻修辭。「牡丹，花之富貴者也」＝把牡丹比作富貴的人（暗喻：A 是 B）。\n(B) 藉口是一種止痛劑：「藉口」是「止痛劑」→ 暗喻。\n(A) 類疊；(C) 設問；(D) 誇飾。\n★ 譬喻四要素：喻體、喻詞、喻依；「A 是 B」「A，B 也」都是暗喻。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-18", "no": "18", "c": "k5", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「芝蘭生於深林，不以無人而不芳；君子修道立德，不為窮困而改節。」這句話的涵義同於下列何者？", "o": ["風雨如晦，雞鳴不已", "己立立人，己達達人", "通權達變，因時制宜", "入芝蘭之室，久而不聞其香"], "a": 0, "e": "考點：文意理解——君子處困境不改節操。\n題文：芝蘭不因沒人欣賞而不香；君子不因窮困而改變節操。\n(A) 風雨如晦，雞鳴不已：環境再黑暗，雞仍按時啼叫 → 比喻君子處亂世不改其節。\n(B) 推己及人；(C) 隨機應變；(D) 久處善人之中而不覺其美。\n★ 不因外在環境改變操守 → 出淤泥而不染。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-19", "no": "19", "c": "k12", "src": "講義 第75頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「洛陽之俗，大抵好牡丹，春時城中無分貴賤皆插花，雖負擔者亦然。花開時，士庶競為遊邀，至花落乃罷。禁中遣使至東都，採牡丹以充貢，歲不過進姚黃魏紫三數朵。以菜葉護之，裹以竹籠，覆以蠟紙，附驛騎日夜兼程進獻。」根據這段文字，下列關於牡丹的敘述何者最恰當？", "o": ["姚黃魏紫指的是富貴人家", "洛陽權貴才有資格賞牡丹", "牡丹運送前須以蠟紙封存", "牡丹運送時以菜葉保護"], "a": 3, "e": "考點：閱讀理解（歐陽脩〈洛陽牡丹記〉）。\n文中「以菜葉護之，裹以竹籠，覆以蠟紙」→ (D) 用菜葉保護。\n(A) 錯：姚黃、魏紫是牡丹的名貴品種。\n(B) 錯：「無分貴賤皆插花」。\n(C) 錯：蠟紙是覆蓋竹籠，不是封存。\n★ 閱讀題：選項要回到原文逐字對照。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-20", "no": "20", "c": "k4", "src": "講義 第76頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "愛蓮說一文中指出了三種人生取向。下列有關本文的說明何者正確？", "o": ["以菊象徵隱士，菊是本文主體", "以牡丹象徵富貴，牡丹是本文主體", "以蓮象徵君子，蓮是本文主體", "陶淵明代表菊，周敦頤代表蓮，兩者是本文主體"], "a": 2, "e": "考點：本文主體。\n(C) 正確：以蓮象徵君子，蓮是全文主體。\n菊是「正襯」、牡丹是「反襯」，都是陪襯。\n(D) 錯：陶淵明、周敦頤是愛花的人，不是主體。\n★ 主體：蓮；正襯：菊；反襯：牡丹。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-21", "no": "21", "c": "k5", "src": "講義 第76頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列關於愛蓮說一文句說明的敘述，何者正確？", "o": ["「出淤泥而不染」象徵君子不隨波逐流", "「可遠觀而不可褻玩焉」表示君子自視甚高，難以親近", "「菊，花之隱逸者也」含有超凡入聖之意", "「牡丹之愛，宜乎眾矣」點出富貴人人所愛，作者亦不免俗"], "a": 0, "e": "考點：文句涵義。\n(A) 正確：出淤泥而不染＝身處污濁環境也不同流合污、不隨波逐流。\n(B) 錯：可遠觀而不可褻玩＝人格莊重令人敬重，不是自視甚高。\n(C) 錯：隱逸是隱居避世，不是超凡入聖。\n(D) 錯：宜乎眾矣是委婉批評，作者不愛牡丹。\n★ 出淤泥而不染＝潔身自愛。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-22", "no": "22", "c": "k6", "src": "講義 第76頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "愛蓮說一文作者用肯定的語氣說：「菊之愛，陶後鮮有聞」，用含蓄的語氣問：「蓮之愛，同予者何人？」再用委婉貶責的語氣說：「牡丹之愛，宜乎眾矣！」可見作者是一個怎樣的人？", "o": ["愛之深，責之切", "恨鐵不成鋼", "君子責人也輕以約", "君子言先不言後"], "a": 2, "e": "考點：從語氣看作者為人。\n作者對菊肯定、對蓮含蓄感嘆、對牡丹只「委婉」貶責，不嚴厲批評 → (C) 君子責人也輕以約（要求別人寬厚簡約）。\n(A)(B) 是嚴厲責備；(D) 與題意無關。\n★ 「宜乎眾矣」＝委婉，不是痛罵。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-23", "no": "23", "c": "k6", "src": "講義 第76頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「牡丹之愛，宜乎眾矣！」關於此句的涵義，下列何者說明最正確？", "o": ["說明牡丹容易種植，是普通的花種", "說明牡丹花和菊花、蓮花相比，毫不遜色", "表達自己與眾人相同，也喜好牡丹", "牡丹象徵富貴，說明一般人都喜歡追求富貴"], "a": 3, "e": "考點：「牡丹之愛，宜乎眾矣」。\n牡丹象徵富貴，喜愛牡丹的人應該很多 → (D) 一般人都喜歡追求富貴，含委婉諷刺。\n(A)(B) 與花的種植、比美無關；(C) 錯：作者「獨愛蓮」。\n★ 宜乎＝應當；眾＝多。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-24", "no": "24", "c": "k8", "src": "講義 第76頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「屢見不鮮」與「陶後鮮有聞」的「鮮」字的音義關係為何？", "o": ["音同義異", "音異義同", "音義皆異", "音義皆同"], "a": 2, "e": "考點：「鮮」的音義。\n屢見不「鮮」：ㄒㄧㄢ，新奇。\n陶後「鮮」有聞：ㄒㄧㄢˇ，少。\n讀音不同、意義也不同 → (C) 音義皆異。\n★ 鮮ㄒㄧㄢˇ＝少：鮮有、鮮為人知、寡廉鮮恥。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-25", "no": "25", "c": "k11", "src": "講義 第76頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列各詠花詩所描述的花，何者搭配正確？", "o": ["落盡殘紅始吐芳，佳名喚作百花王。競誇天下無雙豔，獨占人間第一香：梅花", "花開不並百花叢，獨立疏籬趣未窮。寧可枝頭抱香死，何曾吹墮北風中：菊花", "眾芳搖落獨鮮妍，占盡風情向小園。疏影橫斜水清淺，暗香浮動月黃昏：牡丹", "春紅始謝又秋紅，息國亡來入楚宮。應是蜀冤啼不盡，更憑顏色訴秋風：蓮"], "a": 1, "e": "考點：詠花詩辨識。\n(B) 鄭思肖〈寒菊〉：「寧可枝頭抱香死」——菊花凋謝不落瓣 → 菊花，正確。\n(A) 百花王、天下無雙豔 → 牡丹。\n(C) 疏影橫斜、暗香浮動（林逋〈山園小梅〉）→ 梅花。\n(D) 蜀冤啼不盡（杜鵑鳥啼血）→ 杜鵑花。\n★ 百花王＝牡丹；暗香疏影＝梅；抱香死＝菊。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-26", "no": "26", "c": "k5", "src": "講義 第76頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「水，君子也。其性沖，其質白，其味淡，其用也，可以淬不潔而使潔，即沸湯中投以油，亦自分別而不相混，誠哉君子也。」上文中「油水亦自分別而不相混」近似於愛蓮說一文中的哪一項君子之德？", "o": ["濯清漣而不妖", "出淤泥而不染", "香遠益清，亭亭淨植", "可遠觀而不可褻玩"], "a": 1, "e": "考點：文意對應蓮的特質。\n「沸湯中投以油，亦自分別而不相混」＝處在混雜環境中仍不被混同 → (B) 出淤泥而不染。\n(A) 濯清漣而不妖＝不媚俗；(C) 美名遠播、端正挺立；(D) 令人敬重。\n★ 不相混＝不同流合污。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-27", "no": "27", "c": "k12", "src": "講義 第76頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "MBTI測驗指標與對應的人格類型。根據此表，下列敘述何者正確？", "o": ["MBTI有八大測驗指標", "表中共列出四種人格類型", "實感型人格習慣以未來推測判斷事物", "系統型人格做事習慣有條不紊"], "a": 3, "e": "考點：圖表判讀（MBTI 四個維度）。\n表中有 4 組指標（外向／內向、實感／直覺、理性／感性、評判／彈性），共 8 種傾向。\n(A) 錯：是四大指標。\n(B) 錯：不只四種。\n(C) 錯：實感型重視眼前的事實與經驗，靠想像、推測未來的是直覺型。\n(D) 正確：評判（系統型）做事有計畫、有條不紊。\n★ 圖表題：先看表頭（有幾個維度），再對選項。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "<div class=\"fig\"><span class=\"lb\">圖表（依題意重建）MBTI 測驗四個指標</span><div class=\"tbl\" style=\"margin:.3rem 0 0;background:#fff\"><table style=\"min-width:0\"><thead><tr><th>指標</th><th>傾向一</th><th>傾向二</th></tr></thead><tbody><tr><td>能量來源</td><td>外向：從與人互動中獲得能量</td><td>內向：從獨處沉澱中獲得能量</td></tr><tr><td>獲取資訊</td><td>實感：重視眼前的事實與實際經驗</td><td>直覺：重視想像、推測未來的可能</td></tr><tr><td>做決定</td><td>理性：依邏輯分析判斷</td><td>感性：依感受與價值判斷</td></tr><tr><td>生活態度</td><td>評判（系統型）：有計畫、有條不紊</td><td>彈性：隨機應變、保持彈性</td></tr></tbody></table></div></div>", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-28", "no": "28", "c": "k5", "src": "講義 第77頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "魯迅做古文和做好人的祕訣：「做下去，年深日久之後，先生就不再刪改你的文章了，只在篇末批此『有書有筆』、『□□□□』之類，到這時候，即可以算作『通』。」根據這段話的文意，缺空處填入何者最恰當？", "o": ["出淤不染", "中通外直", "不蔓不枝", "宜乎眾矣"], "a": 2, "e": "考點：文句運用（魯迅〈做古文和做好人的祕訣〉）。\n老師在文章後批「有書有筆，不蔓不枝」——稱讚文章簡潔、不拖泥帶水。\n「不蔓不枝」原指蓮莖不生枝蔓，後來也用來形容文章簡潔扼要 → (C)。\n★ 不蔓不枝：蓮＝不攀附；文章＝簡潔。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-29", "no": "29", "c": "k12", "src": "講義 第77頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "閱讀選文摘錄：蓮花顧名思義是蓮的花，蓮子是蓮的果實，蓮藕則是蓮的「地下莖」。……荷葉行光合作用，地下的蓮藕儲存養分，生出蓮子後，養分也會供給蓮子，若要蓮藕長得好，蓮子往往就小，有的品種甚至不會開花或花朵稀少。", "fig": "", "q": "根據這段介紹，有些品種的蓮不會開花的原因為何？", "o": ["避免蓮花跟蓮藕競爭養分", "蓮本身無法耐高溫", "避免授粉後的凋謝", "為了讓蓮藕長得好"], "a": 0, "e": "考點：閱讀理解。\n文中：蓮藕儲存養分，生出蓮子後養分也會供給蓮子，「若要蓮藕長得好，蓮子往往就小」——開花結子會跟蓮藕搶養分，所以有些以採藕為主的品種不開花或花少 → (A)。\n(B)(C) 文中沒提到。\n★ 因果題：找「若要……就……」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-30", "no": "30", "c": "k12", "src": "講義 第77頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "閱讀選文詩句：以青銅的鎧甲，黃金的劍戟／刺退層層包圍的黑夜／芭蕉在風裡招展綠色的大旗／牽牛花吹起藍色的喇叭，野百合搖響銀鈴／慶祝你的勝利，迎來晨曦", "fig": "", "q": "請問下列何者是這首詩所詠之物？", "o": ["鳳凰花", "向日葵", "馬蹄蓮", "聖誕紅"], "a": 1, "e": "考點：新詩所詠之物。\n「青銅的鎧甲，黃金的劍戟」＝綠色的莖葉、金黃色的花瓣；「刺退黑夜，迎來晨曦」＝迎著太陽 → (B) 向日葵。\n★ 詠物詩：抓顏色＋習性（迎向太陽）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-31", "no": "31", "c": "k12", "src": "自修 第107頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「蝸以涎見覓，蟬以聲見黏，螢以光見獲。故愛身者，不貴赫赫之名。」這句話的涵義與下列何者最接近？", "o": ["人過留名，雁過留聲", "所榮者善行，所恥者惡名", "名不可簡而成，譽不可巧而立", "樹大招風風損樹，人為名高名喪身"], "a": 3, "e": "考點：文意理解。\n蝸牛因黏液被找到、蟬因叫聲被黏住、螢火蟲因光被抓到——太顯眼反而招禍，所以愛惜自己的人不追求顯赫的名聲 → (D) 樹大招風風損樹，人為名高名喪身。\n(A) 鼓勵留名；(B)(C) 講善惡、名譽要靠實力。\n★ 關鍵：名聲太大反而招害。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-32", "no": "32", "c": "k12", "src": "自修 第107頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "【甲】觀其交遊，則其賢、不肖可察也。【乙】貴視其所舉，富視其所與，貧視其所不取，窮視其所不為。這兩句話主要是在說明下列何者？", "o": ["修身的原則", "做事的態度", "識人的方法", "擇友的要件"], "a": 2, "e": "考點：文意理解。\n【甲】觀察一個人交什麼朋友，就知道他賢不賢；【乙】看一個人顯貴時推舉誰、富有時跟誰往來、貧窮時不拿什麼、困頓時不做什麼 → 都是 (C) 識人的方法。\n★ 「觀其……則……可察」＝看人的方法。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-33", "no": "33", "c": "k9", "src": "自修 第107頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「修身以為弓，矯思以為矢，立義以為的，奠而後發，發必中矣。」句中「矯」字的意義，與下列何者最接近？", "o": ["「矯」世勵俗", "「矯」若遊龍", "「矯」捷身手", "「矯」託天命"], "a": 0, "e": "考點：「矯」的字義。\n「矯思以為矢」：矯＝矯正、使正直。\n(A) 矯世勵俗：矯正世風 → 相同。\n(B) 矯若遊龍、(C) 矯捷身手：矯健、強健。\n(D) 矯託天命：假託、假借。\n★ 矯：矯正／矯健／矯詔（假託）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-34", "no": "34", "c": "k8", "src": "自修 第108頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的字，何組讀音相同？", "o": ["反「省」自己／節「省」花費", "強力遊「說」／「說」服技巧", "味道「鮮」美／「鮮」為人知", "正直挺「重」／「重」修舊好"], "a": 1, "e": "考點：破音字。\n(B) 遊「說」ㄕㄨㄟˋ／「說」服ㄕㄨㄟˋ → 讀音相同。\n(A) 反「省」ㄒㄧㄥˇ／節「省」ㄕㄥˇ。\n(C) 「鮮」美ㄒㄧㄢ／「鮮」為人知ㄒㄧㄢˇ。\n(D) 「重」ㄓㄨㄥˋ（穩重）／「重」修舊好ㄔㄨㄥˊ（再）。\n★ 說服、遊說的「說」都讀ㄕㄨㄟˋ。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-35", "no": "35", "c": "k8", "src": "自修 第108頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的注音寫成國字後，何組字形相同？", "o": ["為官「ㄍㄢ」正／百葉窗「ㄍㄢ」", "肆意「ㄎㄢ」罵／疾病「ㄎㄢ」延", "解「ㄊㄧˊ」事理／分崩離「ㄊㄧˊ」", "洗「ㄉㄧˊ」衣物／拔「ㄉㄧˊ」人才"], "a": 3, "e": "考點：同音字辨形。\n本題選項轉檔時有誤，請對照自修第 108 頁原題。依常見考法推測：\n解「析」事理／分崩離「析」→ 字形相同（都是「析」）。\n洗「滌」ㄉㄧˊ／拔「擢」ㄓㄨㄛˊ → 字形不同。\n★ 字形題：每組都寫出國字再比。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "D"}, {"id": "c4-36", "no": "36", "c": "k12", "src": "自修 第108頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列文句，何者用字最為精簡？", "o": ["他說世上能有一個知己，便不會遺憾", "林和靖歸隱在西湖，賞梅養鶴，終身不嫁娶", "唱片銷售欠佳的演藝圈歌壇新人，需要多演出節目來宣傳自己", "儘管大家都勸媽媽買新衣服，但是節儉的媽媽還是吝惜捨不得"], "a": 0, "e": "考點：用字精簡（找贅字）。\n(A) 沒有多餘字詞，最精簡。\n(B) 「終身不嫁娶」：林和靖是男子，只需「不娶」。\n(C) 「演藝圈歌壇」意思重複。\n(D) 「吝惜」「捨不得」意思重複。\n★ 找意思重複的詞，刪掉後意思不變的就是贅字。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-37", "no": "37", "c": "k9", "src": "自修 第108頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的字，何組意思相同？", "o": ["精「益」求精／延年「益」壽", "「盛」愛牡丹／共襄「盛」舉", "不可褻玩「焉」／心不在「焉」", "「宜」乎眾矣／不「宜」妄自菲薄"], "a": 0, "e": "考點：一字多義。教用答案為 (A)，但這題值得再核對：\n(A) 精「益」求精＝更加；延年「益」壽＝增加 → 嚴格說意思不同。\n(B) 「盛」愛＝非常；共襄「盛」舉＝盛大。\n(C) 褻玩「焉」＝句末語氣詞；心不在「焉」＝在這裡（於此）。\n(D) 「宜」乎眾矣＝應當；不「宜」妄自菲薄＝不應當 → 看起來意思相同。\n★ 宜乎＝應當；益＝更加（香遠益清、精益求精、多多益善）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "A"}, {"id": "c4-38", "no": "38", "c": "k9", "src": "自修 第108頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「濯清漣而不妖」這句話中的「而」字是表示轉折關係，下列「而」字何者也是表示轉折關係？", "o": ["人「而」無信", "學「而」時習之", "出淤泥「而」不染", "從上「而」下"], "a": 2, "e": "考點：「而」表轉折（卻）。\n(C) 出淤泥「而」不染＝卻 → 轉折，與濯清漣而不妖相同。\n(A) 人「而」無信＝如果 → 假設。\n(B) 學「而」時習之＝並且 → 順接。\n(D) 從上「而」下＝到 → 連接。\n★ 前後意思相反 → 轉折（卻）。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-39", "no": "39", "c": "k11", "src": "自修 第108頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "連假期間，周敦頤與親友到白河賞蓮，蓮花田的美景讓大家流連忘返，讚嘆連連。下列四人使用有關「蓮」的詞語，何者最恰當？", "o": ["周星星：看到眼前這幅「藕斷絲連」的勝景，便覺得此次不虛此行了", "敦宜老爸：漫步在蓮花田邊，令我「步步生蓮花」，心情舒暢", "蘇西坡：這一池「出水芙蓉」讓我想起敦宜文章的清新風格呢", "淵明：回想到中午的蓮花大餐，就覺得「舌粲蓮花」，念念不忘"], "a": 2, "e": "考點：與蓮有關的詞語運用。\n(C) 出水芙蓉：形容詩文清新自然（或女子清麗）→ 正確。\n(A) 藕斷絲連：比喻關係未完全斷絕，不能形容美景。\n(B) 步步生蓮花：形容女子步態優美，不用於自己心情。\n(D) 舌粲蓮花：形容口才好，不是食物好吃。\n★ 芙蓉＝蓮花。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-40", "no": "40", "c": "k11", "src": "自修 第108頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列與「花」有關的成語，何者具有負面意義？", "o": ["花容月貌", "舌粲蓮花", "夢筆生花", "花言巧語"], "a": 3, "e": "考點：成語的褒貶。\n(D) 花言巧語：虛偽動聽的話 → 負面。\n(A) 花容月貌：女子美麗。\n(B) 舌粲蓮花：口才好。\n(C) 夢筆生花：文思大進、才華洋溢。\n★ 花言巧語＝騙人的話（貶義）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-41", "no": "41", "c": "k10", "src": "自修 第108頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「菊，花之隱逸者也；牡丹，花之富貴者也；蓮，花之君子者也。」這段話運用下列何種修辭法？", "o": ["譬喻兼誇飾", "誇飾兼映襯", "轉化兼排比", "排比兼譬喻"], "a": 3, "e": "考點：辨識修辭。\n三句句型相同「○，花之○○者也」連用 → 排比；把花比作隱逸者、富貴者、君子 → 譬喻（暗喻）。\n所以是 (D) 排比兼譬喻。\n★ 三句以上結構相似＝排比；A，B 也＝暗喻。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-42", "no": "42", "c": "k10", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "愛蓮說文末提到：「蓮之愛，同予者何人？」其實就是「愛蓮，同予者沒有多少人」的意思。下列文句，何者也是使用這種問法？", "o": ["問君何能爾？心遠地自偏", "為什麼來的總要逝去", "誰不或多或少地詛咒人生", "我為什麼卻不感謝老天爺"], "a": 2, "e": "考點：激問（答案在問題的反面）。\n「同予者何人？」＝沒有幾個人 → 激問。\n(C) 誰不或多或少地詛咒人生？＝每個人都會 → 激問。\n(A) 問君何能爾？心遠地自偏 → 自問自答（提問）。\n(B)(D) 是單純發問的懸問。\n★ 激問：問句裡藏著相反的答案。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-43", "no": "43", "c": "k11", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「這項技術能夠□□全球，原因可能是負責研發的工程師對於夜騎自行車□□□□。他認為在僻靜的道路途中，才能真正傾聽自我的內心□□，並清空思緒，保持良好的身心狀況，故能迎接新挑戰。」根據文意脈絡，空格處依序填入下列何者最恰當？", "o": ["獨步／匠心獨運／獨到", "獨步／情有獨鍾／獨白", "獨享／匠心獨運／獨到", "獨享／情有獨鍾／獨白"], "a": 1, "e": "考點：詞語填空。\n獨步全球（獨一無二、領先）→ 對夜騎自行車情有獨鍾（特別喜愛）→ 傾聽內心的獨白（自言自語） → (B)。\n「獨享」不能接「全球」；「匠心獨運」是構思巧妙，不是喜好；「獨到」是見解獨特。\n★ 情有獨鍾＝特別喜愛某事物。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-44", "no": "44", "c": "k9", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列文句「　」中的詞語，何者詞性前後相同？", "o": ["「可愛」園區裡的動物，都非常「可愛」", "「富貴」如浮雲，可見「富貴」的生活也不可靠", "「淤泥」形成的泥火山，簡直成了「淤泥」的世界", "陳摶是個「隱居」的人，他在華山「隱居」"], "a": 2, "e": "考點：詞性判斷。\n(C) 「淤泥」形成泥火山／「淤泥」的世界：兩個都是名詞 → 相同。\n(A) 前一個「可愛」修飾園區，後一個是形容動物；本選項轉檔可能有缺字。\n(B) 「富貴」如浮雲：名詞；「富貴」的生活：形容詞。\n(D) 「隱居」的人：形容詞；在華山「隱居」：動詞。\n★ 放在「的」前面修飾名詞 → 多半是形容詞；接在主詞後當動作 → 動詞。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-45", "no": "45", "c": "k7", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「之」字在古文中的用法相當多元，愛蓮說一文中，「蓮之愛」的「之」字為助詞，表示賓語提前。下列「之」字的詞性及用法，何者與此相同？", "o": ["項為「之」強", "水陸草木「之」花", "父母唯其疾「之」憂", "敬人者，人恆敬「之」"], "a": 2, "e": "考點：「之」作提賓助詞。\n「蓮之愛」＝愛蓮。\n(C) 父母唯其疾之憂＝父母唯憂其疾 → 「之」提賓，相同。\n(A) 項為之強＝脖子因此變硬，「之」代詞（它）。\n(B) 草木之花：「的」。\n(D) 人恆敬之：代詞（他）。\n★ 能把「之」拿掉、把後面的動詞搬到前面還原 → 提賓助詞。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-46", "no": "46", "c": "k10", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「牡丹之愛，宜乎眾矣！」這句話傳達出委婉貶責的語氣，與下列何者相同？", "o": ["大約大去之期不遠矣", "菊之愛，陶後鮮有聞", "這般占小便宜的人，應當不少", "拜您之賜，我現在還拄著拐杖走路呢"], "a": 3, "e": "考點：委婉貶責（語帶諷刺）。\n「牡丹之愛，宜乎眾矣」表面平淡，實為委婉批評。\n(D) 拜您之賜，我現在還拄著拐杖走路：表面感謝，實際責怪 → 相同。\n(A) 單純陳述；(B) 肯定菊的語氣；(C) 直接批評，不委婉。\n★ 委婉貶責：話說得客氣，意思是責怪。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-47", "no": "47", "c": "k5", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "周周在寫作文時，想要形容某人「胸懷通達坦蕩、不攀附權勢、不結黨營私。內心光明正大，為人正直」，他引用下列哪一文句最恰當？", "o": ["出淤泥而不染", "中通外直，不蔓不枝", "可遠觀而不可褻玩焉", "濯清漣而不妖"], "a": 1, "e": "考點：蓮花特質對應君子之德。\n胸懷坦蕩、為人正直 → 中通外直；不攀附權勢、不結黨營私 → 不蔓不枝 → (B)。\n(A) 潔身自愛；(C) 莊重令人敬重；(D) 不媚俗。\n★ 中通＝心胸通達；外直＝行為正直；不蔓不枝＝不攀附。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-48", "no": "48", "c": "k5", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "周敦頤在愛蓮說一文中把蓮花比喻為君子，「可遠觀而不可褻玩焉」這段文字最能呼應論語中的哪一句話？", "o": ["君子成人之美", "君子有終身之憂", "君子坦蕩蕩", "君子不重則不威"], "a": 3, "e": "考點：文句呼應論語。\n「可遠觀而不可褻玩」＝君子莊重，令人敬而不敢輕慢 → (D) 君子不重則不威（不莊重就沒有威嚴）。\n(A) 成全別人；(B) 君子終身憂慮修德；(C) 心胸坦蕩（較接近中通）。\n★ 莊重才有威嚴 → 可遠觀而不可褻玩。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-49", "no": "49", "c": "k6", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「蓮之愛，同予者何人？」這句話所蘊含的意旨最可能是下列何者？", "o": ["作者感嘆世上有道德理想的人太少", "說明愛蓮的人太少了", "說明大多數的人不懂得愛蓮花", "說明蓮花之美麗芬芳"], "a": 0, "e": "考點：「蓮之愛，同予者何人？」\n蓮象徵君子，作者感嘆跟自己一樣追求君子品德的人太少 → (A)。\n(B)(C)(D) 只停留在花的層面，沒讀出象徵意義。\n★ 讀到花，要想到「人」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-50", "no": "50", "c": "k5", "src": "自修 第109頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "周敦頤愛蓮說細數蓮的特質，它們都象徵著君子的德行，其中不包含下列何者？", "o": ["博施濟眾，仁民愛物", "鄙夷富貴，不攀權勢", "潔身自好，不隨流俗", "高風亮節，清譽遠播"], "a": 0, "e": "考點：蓮花象徵的君子之德。\n(B) 不攀權勢＝不蔓不枝；(C) 潔身自好＝出淤泥而不染；(D) 清譽遠播＝香遠益清。\n(A) 博施濟眾、仁民愛物是對百姓的仁愛作為，文中沒有提到 → 不包含。\n★ 蓮的七德講「個人修養」，沒有講「救濟百姓」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-51", "no": "51", "c": "k5", "src": "自修 第110頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "根據愛蓮說一文，周敦頤愛蓮的原因不包含下列何者？", "o": ["蓮花出淤泥而不染，如君子潔身自好", "蓮花中通外直，如君子剛正不阿", "蓮花香遠益清，如君子德芳遠播", "蓮花經霜猶傲，如君子風骨欽崎"], "a": 3, "e": "考點：作者愛蓮的原因。\n(A)(B)(C) 都是課文提到的蓮花特質。\n(D) 「經霜猶傲」是菊花（秋天傲霜開放）的特質，不是蓮 → 不包含。\n★ 傲霜＝菊；出淤泥＝蓮。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-52", "no": "52", "c": "k7", "src": "自修 第110頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列文句的詞語順序經過調整後，何者文意不變？", "o": ["「私擬作群鶴舞空」 → 群鶴舞空擬作私", "「可遠觀而不可褻玩焉」 → 焉可遠觀而不可褻玩", "「菊之愛，陶後鮮有聞」 → 陶後鮮聞愛菊之人", "「三人行必有我師焉」 → 我師焉必有三人行"], "a": 2, "e": "考點：倒裝句還原。\n(C) 「菊之愛，陶後鮮有聞」＝愛菊的人，陶淵明以後很少聽說 → 改成「陶後鮮聞愛菊之人」文意不變。\n(A)(B)(D) 調整後主客顛倒、語意不通。\n★ 菊之愛＝愛菊。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-53", "no": "53", "c": "k3", "src": "自修 第110頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "由愛蓮說一文可知，作者寫作本文的用意最可能是下列何者？", "o": ["諷刺人心不古", "抒發個人的心志", "景仰生活的純真", "宣揚社會的道德理想"], "a": 1, "e": "考點：寫作用意。\n本文托物言志，藉蓮花寫君子，抒發作者自己潔身自愛、不慕富貴的心志 → (B)。\n(A) 末段雖有委婉批評，但不是主要目的；(D) 宣揚社會理想太過擴大。\n★ 托物言志＝寫物是為了「說自己的志向」。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-54", "no": "54", "c": "k11", "src": "自修 第110頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "張潮認為人生在世若能有一個知己，便可以無憾。下列各物與人的配對，何者正確？", "o": ["梅／陶淵明", "荔枝／王昭君", "鵝／王羲之", "茶／李白"], "a": 2, "e": "考點：古人與其知己之物。\n(C) 鵝—王羲之：正確（愛鵝，曾以字換鵝）。\n(A) 梅的知己是林逋；陶淵明愛菊。\n(B) 荔枝—楊貴妃（一騎紅塵妃子笑）。\n(D) 茶—陸羽；李白愛酒。\n★ 菊陶、蓮周、梅林、鵝王、茶陸。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-55", "no": "55", "c": "k6", "src": "自修 第110頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「噫！菊之愛，陶後鮮有聞。蓮之愛，同予者何人？牡丹之愛，宜乎眾矣！」這段話的涵義最可能是下列何者？", "o": ["世風日下，人心不古", "菊、蓮不如牡丹的富貴可愛", "獨善其身者少，兼善天下者多", "品德高潔的君子難求，好功名利祿的世人眾多"], "a": 3, "e": "考點：末段三嘆。\n愛菊（隱士）少、愛蓮（君子）更少、愛牡丹（追富貴）的人多 → (D) 品德高潔的君子難求，好功名利祿的世人眾多。\n(A) 太籠統；(B) 錯：作者並不認為牡丹較可愛；(C) 說反了。\n★ 末段結論：君子少，追富貴的人多。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-56", "no": "56", "c": "k6", "src": "自修 第110頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "宋代理學之祖周敦頤對於「花」的形象與所表現的人格特質判定，下列敘述何者最恰當？", "o": ["世人愛牡丹：豔冠群芳，隨俗浮沉，故委婉地貶責", "蘭：香遠益清，潔身自愛，以「濯清漣而不妖」贊之", "蓮：具君子之德，象徵環境之艱苦仍不屈，以「清雅虛心」評之", "陶淵明愛菊：眾芳無穢時，菊空傲自賞，未免太自命清高"], "a": 0, "e": "考點：三花的形象與人格。\n(A) 正確：世人愛牡丹，象徵追逐富貴、隨俗浮沉，作者委婉貶責。\n(B) 錯：文中沒有蘭，香遠益清是蓮。\n(C) 錯：蓮不是「清雅虛心」的評語；中通是坦蕩。\n(D) 錯：作者對陶淵明愛菊是肯定，不是批評。\n★ 對菊：肯定；對蓮：感嘆；對牡丹：委婉貶責。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-57", "no": "57", "c": "k5", "src": "自修 第110頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "愛蓮說一文藉蓮的特質來象徵君子之德。下列說明何者正確？", "o": ["不蔓不枝：品格高尚，美名遠播", "中通外直：潔身自愛，不隨俗浮沉", "濯清漣而不妖：節操高雅，不逢迎媚世", "出淤泥而不染：品格高傲，讓人不敢輕慢戲弄"], "a": 2, "e": "考點：蓮的特質與君子之德。\n(C) 濯清漣而不妖：節操高雅，不逢迎媚世 → 正確。\n(A) 不蔓不枝＝不攀附權貴；美名遠播是香遠益清。\n(B) 中通外直＝坦蕩正直；潔身自愛是出淤泥而不染。\n(D) 出淤泥而不染＝潔身自愛；令人不敢輕慢是可遠觀而不可褻玩。\n★ 一句對一德，背熟口訣就不會混。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-58", "no": "58", "c": "k12", "src": "自修 第110頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「孟子有一次和他的學生萬章談到：『孔子很厭惡那些八面玲瓏、經常奉承討好的人。這種人雖然在鄉里被稱作好人，但實際上是言行不符、偽善欺壓的偽君子。這種人同乎流俗，合乎汙世，看似好人，實際根本不會有好的作為。』」根據這段文字，下列說明何者錯誤？", "o": ["這是成語「同流合污」的典故", "孟子認為在鄉里被稱作好人的人皆是偽君子", "「合乎汙世」是指對不合理的現象只會附和", "孟子告誡萬章為人處世應潔身自愛"], "a": 1, "e": "考點：閱讀理解（鄉愿）。\n(B) 錯：孟子批評的是「八面玲瓏、奉承討好」的那種人（鄉愿），不是所有被稱作好人的人都是偽君子。\n(A) 「同乎流俗，合乎汙世」正是「同流合污」的出處。\n(C)(D) 合乎文意。\n★ 「皆」「都」「一定」這類絕對字眼，常是錯誤選項。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-59", "no": "59", "c": "k12", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「如何穿著，就如同如何生活，是你個人的事；但做衣著的奴隸，和做生活的奴隸是一樣的不智。」這段話的主旨最可能是下列何者？", "o": ["活出自我比流行重要", "年輕就是本錢", "只要我喜歡，有什麼不可以", "善於包裝，才能引人注意"], "a": 0, "e": "考點：主旨判斷。\n怎麼穿是個人的事，但被衣著（流行）牽著走，就像被生活奴役一樣不智 → (A) 活出自我比追流行重要。\n(C) 只要我喜歡就可以，忽略了「不做奴隸」的提醒。\n★ 關鍵詞：「奴隸」＝被控制。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-60", "no": "60", "c": "k12", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "泰戈爾：「埋在地下的樹根使樹枝產生果實，卻並不要求什麼報酬。夜把花悄悄地開放了，卻讓白日去領受謝詞。」這段話的涵義與下列哪一句話最接近？", "o": ["聽老人言，吃虧在眼前", "緊行無好步，慢嚼得滋味", "澹然以處世，明道不居功", "沒有梧桐樹，怎招鳳凰來"], "a": 2, "e": "考點：文意理解。\n樹根默默付出不求回報；夜讓花開，卻讓白日領受感謝 → 默默付出、不居功 → (C) 澹然以處世，明道不居功。\n(A) 聽長輩的話；(B) 慢工出細活；(D) 有好條件才能吸引人才。\n★ 不求回報、不居功。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-61", "no": "61", "c": "k11", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "不同的花有不同的意象，如玫瑰表示愛情，火鶴花象徵熱情。下列花卉與意象的配對，何者有誤？", "o": ["鳳凰花／畢業", "楊柳／團圓", "梅花／堅貞不屈", "蓮花／純潔無邪"], "a": 1, "e": "考點：花木意象。\n(B) 錯：楊柳象徵「離別」（古人折柳送別，「柳」諧音「留」），不是團圓。\n鳳凰花—畢業、梅花—堅貞、蓮花—純潔，皆正確。\n★ 柳＝離別；菊＝隱逸；松柏＝堅貞。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-62", "no": "62", "c": "k11", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「雪後尋□，霜前訪□，雨際護□，風外聽□，固野客之閒情，實文人之雅趣。」根據文意脈絡，空格處依序填入下列何者最恰當？", "o": ["梅、蘭、菊、楓", "柏、竹、蘭、菊", "梅、菊、蘭、竹", "松、楓、菊、竹"], "a": 2, "e": "考點：花木的時令與特性（張潮幽夢影）。\n雪後尋「梅」（冬天開）、霜前訪「菊」（秋天開）、雨際護「蘭」（嬌弱）、風外聽「竹」（竹葉沙沙聲）→ (C)。\n★ 梅耐雪、菊傲霜、竹有聲。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-63", "no": "63", "c": "k12", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "韓非子觀行：「有勇之智，而無勇之膽，大功不立。」這句話的涵義與下列何者最接近？", "o": ["老王賣瓜，自賣自誇", "牡丹雖好，綠葉相扶", "食之無味，棄之可惜", "晴帶雨傘，飽帶飢糧"], "a": 1, "e": "考點：文意理解。\n有智謀還要有膽識配合才能成大功 → 好的條件也需要其他條件輔助 → (B) 牡丹雖好，綠葉相扶。\n(A) 自誇；(C) 雞肋；(D) 未雨綢繆。\n★ 兩樣條件相輔相成。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-64", "no": "64", "c": "k11", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列有關「花」的文句，何者解釋不恰當？", "o": ["有意栽花花不發，無心插柳柳成蔭：表示意外收穫", "少年休笑白頭翁，花開能有幾時紅：表示慈悲為懷", "賣花人說花香，賣藥人說藥方：表示自賣自誇", "山重水複疑無路，柳暗花明又一村：表示一線生機"], "a": 1, "e": "考點：俗語涵義。\n(B) 錯：「少年休笑白頭翁，花開能有幾時紅」是說青春短暫、人都會老，勸人不要嘲笑老人，不是慈悲為懷。\n(A) 意外收穫、(C) 自賣自誇、(D) 絕處逢生，皆正確。\n★ 花開幾時紅＝好景（青春）不長。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-65", "no": "65", "c": "k12", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「沒有一朵蓮花能否定淤泥；沒有一個今天的果實能否定昨天的種子。沒有迷失的痛苦，哪有尋得的歡喜？」下列何者最能與這段話的意旨相呼應？", "o": ["今是昨非的觀念是人生的無奈", "走過的每個腳印都是珍貴的資產", "每個人都是命運的傀儡，只能勇往直前", "人生是一條不歸路，錯過的難再找回"], "a": 1, "e": "考點：文意理解。\n蓮花不能否定淤泥、果實不能否定種子、沒有迷失就沒有尋得的歡喜 → 過去的經歷（包括痛苦）都有價值 → (B) 走過的每個腳印都是珍貴的資產。\n(A)(C)(D) 都偏向消極、無奈。\n★ 正面看待過去的每一步。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-66", "no": "66", "c": "k11", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「玉蘭，花中之伯夷也；葵，花中之伊尹也；□，花中之柳下惠也。」空格處填入下列何者最恰當？", "o": ["菊", "梅", "蓮", "水仙"], "a": 2, "e": "考點：以花比人（張潮幽夢影）。\n柳下惠「和而不同」——身處亂世而不失正道，坐懷不亂，正像蓮「出淤泥而不染」→ (C) 蓮。\n伯夷清高（玉蘭潔白）、伊尹積極任事（葵向日）。\n★ 處濁世而不染＝蓮＝柳下惠。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-67", "no": "67", "c": "k5", "src": "自修 第111頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列廣告詞，何者最不能用來宣傳該商品或服務？", "o": ["旅行社：你看聽你的鳥鳴，他看他的日出", "小吃：料好，味好，臺灣第一", "洗衣粉：出淤泥而不染，濯清漣而不妖", "電信業：中通外直，不蔓不枝"], "a": 0, "e": "考點：文句運用在廣告。\n(C) 洗衣粉用「出淤泥而不染」強調洗得乾淨；(D) 電信用「中通外直」強調訊號暢通 → 都巧妙。\n本題 (A) 選項文字轉檔時有誤，教用答案為 (A)，請對照自修第 111 頁原題。\n★ 廣告引用：看原句意思能不能跟商品特色連起來。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "A"}, {"id": "c4-68", "no": "68", "c": "k10", "src": "自修 第112頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "胡適曾鼓勵大家「寧鳴而死，不默而生」。用「寧……不……」對比，藉以強調表達自己意見的重要，就是映襯修辭法。下列文句，何者也使用映襯修辭技巧？", "o": ["開車不喝酒，喝酒不開車", "或列隊而出，或千里單騎，或比肩齊步", "菊之愛，陶後鮮有聞。蓮之愛，同予者何人？牡丹之愛，宜乎眾矣", "從時間，偷一杯咖啡的時間"], "a": 2, "e": "考點：映襯修辭（兩種相反的事物對照）。\n(C) 菊之愛少、蓮之愛更少、牡丹之愛眾多 → 以對比凸顯，屬映襯。\n(A) 開車不喝酒，喝酒不開車 → 回文。\n(B) 或……或…… → 排比。\n(D) 轉化。\n★ 映襯：把相反的兩件事放在一起比，凸顯重點。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-69", "no": "69", "c": "k5", "src": "自修 第112頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "孔子所謂「損者三友」中，「善柔」的朋友是工於諂媚而少誠信的，這與蓮的哪一項特質相違背？", "o": ["出淤泥而不染", "濯清漣而不妖", "香遠益清", "可遠觀而不可褻玩焉"], "a": 1, "e": "考點：「善柔」違背哪一德。\n善柔＝工於諂媚、討好別人 → 違背「濯清漣而不妖」（不妖媚、不逢迎）→ (B)。\n★ 諂媚、討好、取媚 → 對應「不妖」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-70", "no": "70", "c": "k3", "src": "自修 第112頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "李群玉〈蓮葉〉：根是泥中玉，心承露下珠。在君塘上種，埋沒任春蒲。", "fig": "", "q": "作者藉這首小詩，說出了何種感慨？", "o": ["好景不常在", "富貴如浮雲", "人民生活困苦", "君子有志難伸"], "a": 3, "e": "考點：詠物詩的感慨（李群玉〈蓮葉〉）。\n根像泥中的美玉、葉心承接露珠（有美好的品質），卻種在你的池塘裡，任由春天的蒲草掩蓋埋沒 → 有才德卻不被賞識 → (D) 君子有志難伸。\n★ 「埋沒」＝懷才不遇。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-71", "no": "71", "c": "k11", "src": "自修 第112頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "阿丹結婚，好友小明送他一幅畫，叫「富貴到白頭」，畫中有一花一鳥。根據這幅畫的寓意，畫中的一花、一鳥最可能是下列何者？", "o": ["菊、杜鵑", "牡丹、麻雀", "竹、斑鳩", "牡丹、白頭翁"], "a": 3, "e": "考點：花鳥的吉祥寓意。\n「富貴」→ 牡丹；「到白頭」→ 白頭翁（鳥名）→ (D)。\n★ 用諧音、名稱取吉祥意。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-72", "no": "72", "c": "k10", "src": "自修 第112頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「諧音雙關」是利用同音或近音的字詞代替原本的字詞，以產生辭趣的修辭方法。下列文句，何者沒有使用「諧音雙關」？", "o": ["蓮子心中苦，梨兒腹內酸", "不寫情詞不寫詩，一方素帕寄心知，心知接了顛倒看，橫也絲來豎也絲，這般心事有誰知", "蠟燭有心還惜別，替人垂淚到天明", "年年有魚，碎碎平安"], "a": 2, "e": "考點：諧音雙關。\n(A) 蓮子＝憐子、梨兒＝離兒 → 諧音雙關。\n(B) 絲＝思 → 諧音雙關。\n(D) 魚＝餘、碎＝歲 → 諧音雙關。\n(C) 「蠟燭有心」是蠟燭的燭心兼指人的心意，屬「字義雙關」，不是諧音 → 答案。\n★ 諧音雙關：讀音相同；字義雙關：同一個字有兩種意思。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-73", "no": "73", "c": "k12", "src": "自修 第112頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下圖是漢林國中某班四位同學的段考成績圖表，其中何者的表現符合「期望高卻分數低，期望低卻分數高」這兩種情形？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "考點：圖表判讀。\n要找「一科期望高但分數低，另一科期望低但分數高」的人。\n乙：國文期望高、實際分數低；數學期望低、實際分數卻高 → 兩種情形都符合 → (B)。\n★ 圖表題：先把每個人「期望」和「實際」的高低標出來再比。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "<div class=\"fig\"><span class=\"lb\">圖表（依題意重繪，分數為示意）期望成績 vs. 實際成績</span><div class=\"tbl\" style=\"margin:.3rem 0 0;background:#fff\"><table style=\"min-width:0\"><thead><tr><th>同學</th><th>國文 期望</th><th>國文 實際</th><th>數學 期望</th><th>數學 實際</th></tr></thead><tbody><tr><td>甲</td><td>80</td><td>85</td><td>70</td><td>75</td></tr><tr><td>乙</td><td>90</td><td>65</td><td>60</td><td>85</td></tr><tr><td>丙</td><td>60</td><td>55</td><td>65</td><td>60</td></tr><tr><td>丁</td><td>85</td><td>90</td><td>88</td><td>70</td></tr></tbody></table></div></div>", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-74", "no": "74", "c": "k12", "src": "自修 第112頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "李白〈子夜四時歌之一〉：鏡湖三百里，菡萏發荷花。五月西施採，人看隘若耶。回舟不待月，歸去越王家。", "fig": "", "q": "下列關於這首詩的說明，何者最恰當？", "o": ["形式上是五言律詩", "這首歌的題目應為「秋歌」", "本詩借湖畔美景襯托西施之美", "本詩以荷花象徵西施不同流合污"], "a": 2, "e": "考點：詩歌賞析（李白〈子夜四時歌・夏歌〉）。\n(C) 正確：以鏡湖荷花盛開的美景，襯托西施之美（人看隘若耶：看西施的人擠滿若耶溪）。\n(A) 錯：只有六句，不是律詩（律詩八句）。\n(B) 錯：五月荷花開，是「夏歌」。\n(D) 錯：沒有不同流合污的意思。\n★ 律詩八句、絕句四句。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-75", "no": "75", "c": "k8", "src": "自修 第171頁（學力診斷）", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的注音寫成國字後，何組字形相同？", "o": ["睥睨「ㄋㄧˋ」視／隱「ㄋㄧˋ」山林", "貴「ㄓㄨˋ」品／弄「ㄓㄨˋ」之喜", "「ㄕㄨ」諂／「ㄕㄨ」須", "「ㄈㄢˊ」衍／「ㄈㄢˊ」星"], "a": 1, "e": "考點：同音字辨形。\n本題選項轉檔時有誤，請對照自修第 171 頁原題。依常見考法：\n睥「睨」／隱「匿」→ 不同；「繁」衍／「繁」星 → 字形相同。\n★ 字形題：每一組都寫出國字再比。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "B"}, {"id": "c4-76", "no": "76", "c": "k9", "src": "自修 第171頁（學力診斷）", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列「　」中的字，何者詞性與「世人盛愛牡丹」中的「盛」字相同？", "o": ["宜「乎」眾矣", "香遠「益」清", "不蔓不「枝」", "同「予」者何人"], "a": 1, "e": "考點：詞性判斷。「世人盛愛牡丹」的「盛」＝非常，修飾動詞「愛」→ 副詞。\n(B) 香遠「益」清＝更加，修飾「清」→ 副詞，相同。\n(A) 乎：語助詞；(C) 枝：生出枝節，動詞；(D) 予：我，代詞。\n★ 修飾動詞或形容詞、表程度 → 副詞（盛、益、甚、鮮）。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-77", "no": "77", "c": "k11", "src": "自修 第171頁（學力診斷）", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列成語，何者不能用來形容女子的美貌？", "o": ["蒲柳之姿", "亭亭玉立", "出水芙蓉", "花容月貌"], "a": 0, "e": "考點：形容美貌的成語。\n(A) 蒲柳之姿：比喻體質衰弱，或自謙身分低微 → 不能形容美貌。\n(B) 亭亭玉立、(C) 出水芙蓉、(D) 花容月貌：皆形容女子美麗。\n★ 蒲柳易凋零 → 體弱。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-78", "no": "78", "c": "k8", "src": "翰林 A卷・第5回 第 1 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "下列「　」中的形似字，何組讀音相同？", "o": ["牛山「濯濯」／拔「擢」人才", "無「謂」之爭／「喟」然長嘆", "權「宜」之計／地主之「誼」", "「褻」瀆神明／「褒」揚獎勵"], "a": 0, "e": "考點：形近字讀音。\n(A) 牛山「濯濯」ㄓㄨㄛˊ／拔「擢」ㄓㄨㄛˊ → 讀音相同。\n(B) 無「謂」ㄨㄟˋ／「喟」然ㄎㄨㄟˋ。\n(C) 權「宜」ㄧˊ／地主之「誼」ㄧˋ。\n(D) 「褻」瀆ㄒㄧㄝˋ／「褒」揚ㄅㄠ。\n★ 濯（洗）、擢（拔）、濯濯（光禿）都讀ㄓㄨㄛˊ。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-79", "no": "79", "c": "k8", "src": "翰林 A卷・第5回 第 2 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "下列「　」中的注音寫成國字後，何組字形相同？", "o": ["風光明「ㄇㄟˋ」／「ㄇㄟˋ」力四射", "待人「ㄎㄨㄢ」厚／「ㄎㄨㄢ」衣解帶", "養「ㄓㄨㄛˊ」蓄銳／「ㄓㄨㄛˊ」見", "「ㄒㄧㄢ」細／「ㄒㄧㄢ」維"], "a": 3, "e": "考點：同音字辨形。\n(D) 「纖」細／「纖」維 → 字形相同，教用答案。\n(A) 明「媚」／「魅」力 → 不同。\n(C) 養「精」蓄銳？／「卓」見 → 本選項轉檔有誤。\n注意：(B) 待人「寬」厚／「寬」衣解帶 兩個都是「寬」，看起來也相同，請對照原卷第 5-1 頁。\n★ 纖：纖細、纖維、纖纖玉手。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "D"}, {"id": "c4-80", "no": "80", "c": "k10", "src": "翰林 A卷・第5回 第 3 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "「菊，花之隱逸者也」一句使用「譬喻」修辭，下列各句廣告詞中，何者使用相同修辭技巧？", "o": ["用好心腸做好香腸（香腸）", "鬧鐘是都市裡的公雞（鬧鐘）", "泰式雞肉捲，真是泰好吃了（速食店）", "雀甲醬油，溢出全家人的胃（醬油）"], "a": 1, "e": "考點：譬喻修辭。「菊，花之隱逸者也」＝把菊比作隱士（暗喻）。\n(B) 鬧鐘是都市裡的公雞 → 暗喻，相同。\n(A) 類疊；(C) 雙關（泰＝太）；(D) 誇飾＋轉化。\n★ 找「A 是 B」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-81", "no": "81", "c": "k5", "src": "翰林 A卷・第5回 第 4 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "周敦頤在愛蓮說一文中未針對蓮花的哪一種特徵來描述？", "o": ["生長環境", "外型", "香味", "顏色"], "a": 3, "e": "考點：課文描寫蓮的角度。\n生長環境（出淤泥、濯清漣）、外型（中通外直、不蔓不枝、亭亭淨植）、香味（香遠益清）都有寫到。\n(D) 顏色：課文完全沒寫蓮花的顏色 → 答案。\n★ 蓮的描寫：環境、形態、香氣、整體姿態——沒有顏色。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-82", "no": "82", "c": "k6", "src": "翰林 A卷・第5回 第 5 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "愛蓮說一文中，周敦頤對於世人對菊、牡丹和蓮三種植物的態度有所不同的感受，下列說明何者正確？", "o": ["能真正獨善其身的人不少", "能有君子操守的人微乎其微", "追求富貴的人不多", "擁有君子品格的人給予高評價"], "a": 1, "e": "考點：作者對三種人的感受。\n(B) 正確：「蓮之愛，同予者何人」——有君子操守的人微乎其微。\n(A) 錯：獨善其身（隱士）也很少（陶後鮮有聞）。\n(C) 錯：追富貴的人很多（宜乎眾矣）。\n(D) 與題意不符。\n★ 隱者少、君子更少、富貴者多。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-83", "no": "83", "c": "k9", "src": "翰林 A卷・第5回 第 6 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "下列各「　」中的字，何組意思不同？", "o": ["「予」獨愛蓮之出淤泥而不染／「予」豈好辯哉", "心不在「焉」／不可褻玩「焉」", "鮮「有聞」／寡廉「鮮」恥", "其為人也孝弟，而「好」犯上者鮮矣／出淤泥「而」不染"], "a": 3, "e": "考點：一字多義。題目問「意思不同」的。\n(A) 予＝我／予＝我 → 相同。\n(C) 鮮＝少／鮮＝少 → 相同。\n(B) 心不在「焉」＝在這裡；褻玩「焉」＝句末語氣詞 → 意思不同。\n教用答案為 (D)，但 (D) 選項轉檔時有誤（比的是不同的字），依目前文字看 (B) 才是意思不同，請對照原卷第 5-1 頁。\n★ 焉：心不在焉（於此）／褻玩焉（語氣詞）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "D"}, {"id": "c4-84", "no": "84", "c": "k4", "src": "翰林 A卷・第5回 第 7 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "關於愛蓮說一文的寫作技巧，下列敘述何者正確？", "o": ["作者藉蓮花表達自己「懷才不遇」的感慨", "將三種花並列詳加說明，分述其特色", "善用比較和象徵，烘托蓮花的高潔", "文末表現出尊重每個人愛好的多元觀念"], "a": 2, "e": "考點：寫作技巧。\n(C) 正確：以菊、牡丹和蓮比較，並用象徵手法，烘托蓮花的高潔。\n(A) 錯：沒有懷才不遇。\n(B) 錯：詳寫蓮，菊與牡丹只是略寫陪襯。\n(D) 錯：文末對牡丹之愛有委婉批評。\n★ 詳寫蓮、略寫菊與牡丹＝主從分明。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-85", "no": "85", "c": "k5", "src": "翰林 A卷・第5回 第 8 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "周敦頤愛蓮說：「蓮之出淤泥而不染……可遠觀而不可褻玩焉。」這是說明什麼道理？", "o": ["人心隔肚皮，知人知面不知心", "人不可貌相，海水不可斗量", "人必自重，而後人重之", "道不同，不相為謀"], "a": 2, "e": "考點：文句的道理。\n出淤泥而不染……可遠觀而不可褻玩 → 君子自重自愛，別人自然敬重而不敢輕慢 → (C) 人必自重，而後人重之。\n★ 不可褻玩＝人格莊重，令人敬重。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-86", "no": "86", "c": "k4", "src": "翰林 A卷・第5回 第 9 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "愛蓮說一文作者在蓮之外，另外舉出菊和牡丹，其主要用意為何？", "o": ["自己特別喜愛這三種花", "使文章的畫面顏色繽紛", "能凸顯出蓮花形象", "為比較水中和陸地之花"], "a": 2, "e": "考點：寫菊與牡丹的用意。\n用菊（正襯）和牡丹（反襯）來襯托，凸顯蓮花的君子形象 → (C)。\n(A) 錯：作者獨愛蓮。\n★ 寫別的花是為了襯托主角蓮。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-87", "no": "87", "c": "k5", "src": "翰林 A卷・第5回 第 10 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "周敦頤在愛蓮說一文中提到蓮花「可遠觀而不可褻玩焉」，是因為蓮花具有何種特性？", "o": ["富貴嬌豔", "高潔莊重", "安恬自適", "孤芳自賞"], "a": 1, "e": "考點：「可遠觀而不可褻玩焉」。\n蓮花高潔莊重，令人只能遠遠欣賞、不敢輕慢玩弄 → (B) 高潔莊重。\n(A) 是牡丹；(C)(D) 不符合文意。\n★ 不可褻玩＝莊重。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-88", "no": "88", "c": "k5", "src": "翰林 A卷・第5回 第 11 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "周敦頤愛蓮說細數蓮的特質，如：「出淤泥而不染，濯清漣而不妖；中通外直，不蔓不枝；香遠益清，亭亭淨植，可遠觀而不可褻玩焉。」這些都表現君子的德行，其中不包含下列何者？", "o": ["博施濟眾，仁民愛物", "潔身自好，不隨流俗", "不慕富貴，不阿權勢", "高風亮節，清譽遠播"], "a": 0, "e": "考點：蓮花象徵的君子之德。\n(B) 出淤泥而不染；(C) 不蔓不枝；(D) 香遠益清 → 都有。\n(A) 博施濟眾、仁民愛物是對他人的仁愛行為，文中沒有 → 不包含。\n★ 和第 50 題同一類：蓮的七德都是個人修養。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-89", "no": "89", "c": "k5", "src": "翰林 A卷・第5回 第 12 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "周敦頤在愛蓮說一文中，用哪一句話象徵君子「有高雅的節操，不取媚於世」？", "o": ["出淤泥而不染", "中通外直，不蔓不枝", "濯清漣而不妖", "亭亭淨植，可遠觀而不可褻玩焉"], "a": 2, "e": "考點：一句對一德。\n「有高雅的節操，不取媚於世」→ (C) 濯清漣而不妖。\n(A) 潔身自愛；(B) 坦蕩正直、不攀附；(D) 端莊令人敬重。\n★ 不妖＝不媚俗。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-90", "no": "90", "c": "k6", "src": "翰林 A卷・第5回 第 13 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "周敦頤在愛蓮說一文中提到「牡丹之愛，宜乎眾矣」，主要暗示的意思為何？", "o": ["惋惜君子不能潔身自愛", "感嘆隱逸之士多如牛毛", "譏刺附庸風雅者不少", "暗示世人皆汲汲於富貴"], "a": 3, "e": "考點：「牡丹之愛，宜乎眾矣」。\n牡丹象徵富貴，喜愛的人應該很多 → 暗示世人都汲汲追求富貴 → (D)。\n(A)(B)(C) 都與文意不符。\n★ 牡丹＝富貴；宜乎眾矣＝追富貴的人多。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-91", "no": "91", "c": "k6", "src": "翰林 A卷・第5回 第 14 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "關於愛蓮說一文中，周敦頤對「菊」和「蓮」的看法，下列何者敘述正確？", "o": ["菊具備出淤泥而不染的精神", "藉菊暗示有道德理想者極少", "蓮生長在清水卻不顯妖媚，可見其高潔", "蓮處於俗世之中，卻不厭棄世俗，具備「兼善天下」的精神"], "a": 3, "e": "考點：菊與蓮的看法。\n(D) 正確：蓮處濁世而不厭棄世俗，有兼善天下的精神。\n(A) 錯：出淤泥而不染是蓮。\n(B) 錯：藉「蓮」暗示有道德理想者少。\n(C) 本選項文字寫「可見其高潔」看起來也合理，原卷可能是「高傲」，請對照原卷；教用答案為 (D)。\n★ 和第 7 題同一類：注意「高潔」與「高傲」只差一字。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "D"}, {"id": "c4-92", "no": "92", "c": "k5", "src": "翰林 A卷・第5回 第 15 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "愛蓮說一文中提到「中通外直，不蔓不枝」，這是周敦頤用來比喻君子的何種美德？", "o": ["端方正直", "剛毅木訥", "行己有恥", "恭敬謹慎"], "a": 0, "e": "考點：中通外直，不蔓不枝。\n中通（心胸通達坦蕩）、外直（行為正直）、不蔓不枝（不攀附）→ (A) 端方正直。\n(B) 剛毅木訥：剛強、質樸、不善言辭；(C) 行己有恥：有羞恥心；(D) 恭敬謹慎。\n★ 外直＝正直。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-93", "no": "93", "c": "k5", "src": "翰林 A卷・第5回 第 16 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "孔子所謂「損者三友」中，「善柔」的朋友是指諂媚而少誠信的，這和蓮的哪一項特質相違背？", "o": ["出淤泥而不染", "濯清漣而不妖", "中通外直，不蔓不枝", "可遠觀而不可褻玩焉"], "a": 1, "e": "考點：「善柔」違背哪一德。\n善柔＝諂媚討好 → 違背 (B) 濯清漣而不妖（不逢迎、不媚俗）。\n★ 和第 69 題相同，諂媚 ↔ 不妖。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-94", "no": "94", "c": "k12", "src": "翰林 A卷・第5回 第 17 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "「在微饑中升起一朵花，在清冽中映／太陽；／在田田葉波／與／水波間，光／將收回應」下列何者為這首新詩所描寫的對象？", "o": ["桃花", "蓮花", "菊花", "牡丹"], "a": 1, "e": "考點：新詩所詠之物。\n「田田葉波」：田田是形容荷葉茂密相連（江南可採蓮，蓮葉何田田）→ (B) 蓮花。\n★ 田田＝荷葉。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-95", "no": "95", "c": "k12", "src": "翰林 A卷・第5回 第 18 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "「心事在一片碎花布裡蓄意遮掩／琴聲遮掩苦播茶的香氣，我推開窗／與一山微鏽的綠互道日安／時間就停駐在五月／在五月，唧唧堂堂湧上口□□□／以千朵花的笑靨開隘。」缺空處應填入下列何者最恰當？", "o": ["木棉譜", "鳳凰木", "油桐樹", "椰子樹"], "a": 2, "e": "考點：新詩所詠之物。\n「五月」開花、「千朵花」滿山、與山的綠相映 → 五月雪 (C) 油桐樹（客家山區四、五月開白花）。\n(A) 木棉三月開紅花；(B) 鳳凰木六月畢業季開紅花。\n★ 五月雪＝油桐花。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-96", "no": "96", "c": "k5", "src": "翰林 A卷・第5回 第 19 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "下列哪一位歷史人物值得給予「出淤泥而不染」評價？", "o": ["躬耕南陽，因劉備三顧茅廬而出來輔佐的諸葛亮", "明辨是非、高潔自持而遭到放逐的屈原", "因替李陵辯解，而遭受武帝處以宮刑，發憤撰寫史記的司馬遷", "陷害忠良、討好權貴，最終害死岳飛的秦檜"], "a": 1, "e": "考點：「出淤泥而不染」的人物。\n(B) 屈原：在昏亂朝廷中明辨是非、高潔自持，不同流合污 → 符合。\n(A) 諸葛亮重點在出仕輔佐；(C) 司馬遷重點在忍辱著書；(D) 秦檜是反例。\n★ 出淤泥而不染：身處污濁環境而保持清白。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-97", "no": "97", "c": "k11", "src": "翰林 A卷・第5回 第 20 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "下列與植物相關的詩句，何者描述的主要對象為菊花？", "o": ["本無塵土氣，自在水雲鄉。楚楚淨如拭，亭亭生妙香", "灞岸晴來送別頻，相思偏惱不勝春。自家飛絮無算定，爭把長條絆得人", "落盡殘紅始吐芳，佳名喚作百花王。競誇天下無雙豔，獨占人間第一香", "花開不並百花叢，獨立疏籬趣未窮。寧可枝頭抱香死，何曾吹墮北風中"], "a": 3, "e": "考點：詠花詩辨識。\n(D) 「花開不並百花叢」「寧可枝頭抱香死」（鄭思肖〈寒菊〉）→ 菊花。\n(A) 本無塵土氣、亭亭生妙香 → 蓮。\n(B) 灞岸送別、飛絮、長條 → 柳。\n(C) 百花王 → 牡丹。\n★ 和第 25 題同一類。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-98", "no": "98", "c": "k12", "src": "翰林 A卷・第5回 第 21 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "「夜把花悄悄地開放了，卻讓白日去領受謝詞。」下列選項的涵義，何者與此最接近？", "o": ["桃李不言，下自成蹊", "科遇然後學，則勤苦而難成", "君子先擇而後交，小人先交而後擇", "願無伐善，無施勞"], "a": 3, "e": "考點：文意理解。\n夜讓花開，卻讓白日領受感謝 → 做了好事不誇耀、不居功 → (D) 願無伐善，無施勞（不誇耀自己的長處，不張揚自己的功勞）。\n(A) 有德者不必宣揚，自然吸引人；(B) 錯過學習時機；(C) 交友。\n★ 伐善＝誇耀優點；施勞＝表白功勞。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-99", "no": "99", "c": "k5", "src": "翰林 A卷・第5回 第 22 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "「勢利紛華，不近者為潔，近之而不染者尤潔。」關於此段的涵義，最接近下列何者？", "o": ["出淤泥而不染", "中通外直，不蔓不枝", "香遠益清，亭亭淨植", "濯清漣而不妖"], "a": 0, "e": "考點：文意對應。\n不接近權勢富貴的人是潔淨的；接近了卻不被汙染的人更加潔淨 → (A) 出淤泥而不染。\n★ 「近之而不染」＝出淤泥而不染。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-100", "no": "100", "c": "k5", "src": "翰林 A卷・第5回 第 23 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "「蓮花就是荷花，可以說荷花是學名，蓮花是俗名。蓮是『蓮屬』的挺水植物，花與葉都會長出長柄，挺出水面隨風搖曳；睡蓮，則是『睡蓮屬』的浮水植物，又稱『子午蓮』，清晨盛開、下午閉合，花朵較小，蓮葉緊貼著水面，花離水面不到三公分。」根據上文，下列哪一句最能判斷愛蓮說中所寫的是「蓮花」？", "o": ["中通外直", "出淤泥而不染", "香遠益清", "可遠觀而不可褻玩焉"], "a": 0, "e": "考點：閱讀理解。\n依選文：蓮是挺水植物，花葉長出長柄挺出水面；睡蓮葉緊貼水面。\n(A) 「中通外直」寫的是長長的花梗挺直 → 最能判斷是挺水的「蓮」。\n(B)(C)(D) 睡蓮也可能符合，不能分辨。\n★ 判斷題：找「只有蓮有、睡蓮沒有」的特徵。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-101", "no": "101", "c": "k12", "src": "翰林 A卷・第5回 第 24 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "「小時候能吃味道鮮，老時能用有人欲，雖說不是鋼和鐵，渾身骨節壓不彎。」這是在描寫下列何種植物？", "o": ["菊花", "蓮花", "甘蔗", "竹子"], "a": 3, "e": "考點：謎語判讀。\n小時候能吃（竹筍）、味道鮮美；老了能用（做竹器）；雖不是鋼鐵，渾身骨節（竹節）壓不彎 → (D) 竹子。\n★ 「骨節」＝竹節。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-102", "no": "102", "c": "k3", "src": "翰林 A卷・第5回 第 25 題", "st": "考卷", "pk": "ha-5", "pname": "翰林 A卷・第5回（第四課）", "pord": 1, "ctx": "", "fig": "", "q": "李群玉〈蓮葉〉：「根是泥中玉，心承露下珠。在君塘下種，埋沒任春蒲。」作者旨在抒發哪一種感慨？", "o": ["有志難伸", "好景不常", "阿諛奉承", "拋棄虛名"], "a": 0, "e": "考點：詠物詩的感慨（李群玉〈蓮葉〉）。\n根如泥中玉、心承露珠，卻被春蒲埋沒 → 有美質卻不被重用 → (A) 有志難伸。\n★ 和第 70 題同一首詩。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-103", "no": "103", "c": "k8", "src": "翰林 C卷・第5回 第 1 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "下列「　」中的字，何組讀音兩兩相同？", "o": ["「枝繁葉「茂」／幫忙「盛」飯", "「中」通外直／雀屏「中」選", "「予」獨愛蓮／「予」取予求", "陶後「鮮」有聞／新「鮮」可口"], "a": 2, "e": "考點：破音字。\n(C) 「予」獨愛蓮ㄩˊ／「予」取予求ㄩˊ（我）→ 相同。\n(B) 「中」通ㄓㄨㄥ（裡面）／雀屏「中」選ㄓㄨㄥˋ（被選上）。\n(D) 「鮮」有聞ㄒㄧㄢˇ／新「鮮」ㄒㄧㄢ。\n(A) 選項轉檔有誤（茂ㄇㄠˋ、盛飯ㄔㄥˊ）。\n★ 予＝我時讀ㄩˊ；給予讀ㄩˇ。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-104", "no": "104", "c": "k8", "src": "翰林 C卷・第5回 第 2 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "下列「　」中的注音寫成國字後，何組字形相同？", "o": ["閃爍有「ㄍㄨㄤ」／天才橫「ㄧˋ」", "泥沙「ㄩ」積／河港「ㄩ」塞", "「ㄒㄧㄤ」氣逼人／「ㄒㄧㄤ」地求饒", "「ㄨㄢˊ」世不恭／「ㄨㄢˊ」物喪志"], "a": 1, "e": "考點：同音字辨形。\n(B) 泥沙「淤」積／河港「淤」塞 → 字形相同。\n(D) 「玩」世不恭／「玩」物喪志 → 看起來也相同；(A)(C) 選項轉檔有誤。教用答案為 (B)，請對照原卷第 5-1 頁。\n★ 淤：淤泥、淤積、淤塞。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "B"}, {"id": "c4-105", "no": "105", "c": "k9", "src": "翰林 C卷・第5回 第 3 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "下列各「　」中的字，何者經過替換後意思不變？", "o": ["可愛者甚「蕃」：繁", "濯清漣而不「妖」：夭", "香遠「益」清：好", "「宜」乎眾矣：怡"], "a": 0, "e": "考點：字詞替換（通同字）。\n(A) 可愛者甚「蕃」＝「繁」，多 → 替換後意思不變。\n(B) 妖＝豔麗而不端莊；夭＝早死，不同。\n(C) 益＝更加，不能換成「好」。\n(D) 宜＝應當；怡＝愉快。\n★ 蕃通繁＝多。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-106", "no": "106", "c": "k5", "src": "翰林 C卷・第5回 第 4 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "愛蓮說一文中，關於蓮的特質與君子節操的配對，下列何者說明不正確？", "o": ["出淤泥而不染：潔身自愛，不同流合污", "濯清漣而不妖：有高雅的節操，不取媚於世", "中通外直，不蔓不枝：謙虛為懷，不隨便說人是非", "香遠益清：品格高潔，美名遠播"], "a": 2, "e": "考點：蓮的特質與君子之德。\n(C) 錯：中通外直，不蔓不枝＝胸懷坦蕩、行為正直、不攀附權貴，不是「謙虛、不說人是非」。\n(A)(B)(D) 皆正確。\n★ 中通外直＝坦蕩正直；不蔓不枝＝不攀附。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-107", "no": "107", "c": "k9", "src": "翰林 C卷・第5回 第 5 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "下列各「　」中的字，何組意思兩兩相同？", "o": ["「濯」清漣／童山「濯濯」", "陶後鮮有「聞」／「聞」香下馬", "褻玩「焉」／心不在「焉」", "寡廉「鮮」恥／「鮮」為人知"], "a": 3, "e": "考點：一字多義。\n(D) 寡廉「鮮」恥＝少；「鮮」為人知＝少 → 相同。\n(A) 「濯」＝洗；「濯濯」＝光禿的樣子。\n(B) 鮮有「聞」＝聽說；「聞」香下馬＝聞到（用鼻子）。\n(C) 褻玩「焉」＝語氣詞；心不在「焉」＝在這裡。\n★ 鮮ㄒㄧㄢˇ＝少。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-108", "no": "108", "c": "k7", "src": "翰林 C卷・第5回 第 6 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "「蓮之愛」的「之」字是結構性助詞，表示賓語提前。下列各「是」字，何者亦是這樣的用法？", "o": ["抗懷「是」非", "馬首「是」瞻", "自以為「是」", "積非成「是」"], "a": 1, "e": "考點：提賓助詞「是」。\n(B) 馬首「是」瞻＝唯瞻馬首（只看主帥的馬頭行動）→ 「是」把賓語提前，與「蓮之愛」同類。\n(A) 是非：正確；(C) 自以為是：對的；(D) 積非成是：對的。\n★ 提賓三兄弟：唯利是圖、馬首是瞻、蓮之愛。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-109", "no": "109", "c": "k11", "src": "翰林 C卷・第5回 第 7 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "下列與「蓮」的成詞語，何者使用正確？", "o": ["綜藝節目主持人妙語如珠，「蓮開並蒂」，才能贏得觀眾喜愛", "小美的「蓮藕同根」雖纖巧，但常因買不到尺寸而苦惱", "時裝走秀上，模特兒「步步蓮花」，將服裝特色展現無遺", "政壇不僅高考金榜題名，又能抱得美人歸，真可謂「舌粲蓮花」"], "a": 2, "e": "考點：與蓮有關的成語運用。\n(C) 步步蓮花：形容女子步態輕盈優美 → 模特兒走秀，使用正確。\n(A) 蓮開並蒂是夫妻恩愛；口才好是舌粲蓮花。\n(D) 金榜題名又娶得美人，不是舌粲蓮花。\n(B) 選項轉檔有誤。\n★ 步步蓮花＝步態；舌粲蓮花＝口才；並蒂＝成雙。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-110", "no": "110", "c": "k10", "src": "翰林 C卷・第5回 第 8 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "下列文句「　」中的借代詞語，何者借代指稱的人物不恰當？", "o": ["分手後，他依然像塊「牛皮糖」，與前女友糾纏不清", "這位富商年收破億，對待他人卻十分吝嗇，是名副其實的「鐵公雞」", "小明是這次運動會百米賽跑的金牌得主，大家都封他為「領頭羊」", "智愍是個大生的「發電機」，穿什麼衣服都好看"], "a": 2, "e": "考點：借代詞語。\n(C) 錯：「領頭羊」借代帶頭、領導的人，不是用來稱跑得最快的冠軍。\n(A) 牛皮糖：糾纏不休的人；(B) 鐵公雞：一毛不拔的吝嗇鬼 → 正確。\n(D) 選項轉檔有誤（原應是「衣架子」之類）。\n★ 借代：用相關的事物代替本來的人或物。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-111", "no": "111", "c": "k1", "src": "翰林 C卷・第5回 第 9 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "有關「說」這種文體，下列敘述何者正確？", "o": ["又可稱為「雜說」", "用來議論辨析的「論」性質殊異", "專用以解析歷史典故", "篇幅極長，以求精確"], "a": 0, "e": "考點：「說」體。\n(A) 正確：「說」又稱「雜說」。\n(B) 錯：與「論」性質相近。\n(C) 錯：用來解析事理、闡述己意。\n(D) 錯：篇幅多半簡短。\n★ 和第 6 題同一類。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-112", "no": "112", "c": "k10", "src": "翰林 C卷・第5回 第 10 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "「菊，花之隱逸者也；牡丹，花之富貴者也；蓮，花之君子者也。」這句話所使用的修辭法，不包括下列何者？", "o": ["類疊", "排比", "倒反", "譬喻"], "a": 2, "e": "考點：辨識修辭。\n「菊，花之隱逸者也；牡丹，花之富貴者也；蓮，花之君子者也」\n類疊：「花之……者也」重複出現；排比：三句結構相同；譬喻：把花比作人。\n(C) 倒反：說反話（言在此而意在彼），這裡沒有 → 答案。\n★ 倒反＝說反話，例如：「你真行啊！」其實是罵人。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-113", "no": "113", "c": "k9", "src": "翰林 C卷・第5回 第 11 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "下列「　」中的字，何組詞性兩兩相同？", "o": ["不蔓「不枝」／「枝」繁葉茂", "水陸草木「之」花／昂首觀「之」", "可遠「觀」而不可褻玩焉／蔚為奇「觀」", "「攀」在折柳／「攀」龍附鳳"], "a": 3, "e": "考點：詞性判斷。\n(D) 「攀」登／「攀」龍附鳳 → 都是動詞，相同。\n(A) 不蔓不「枝」：動詞（生出枝節）；「枝」繁葉茂：名詞。\n(B) 草木「之」花：助詞（的）；觀「之」：代詞。\n(C) 遠「觀」：動詞；蔚為奇「觀」：名詞（景象）。\n★ 在「不」後面的名詞常轉成動詞（不蔓不枝）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-114", "no": "114", "c": "k11", "src": "翰林 C卷・第5回 第 12 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "下列植物與其代表的涵義，何者配對正確？", "o": ["竹解心虛是我師：青春永駐", "歲寒知松柏之後凋：堅毅不拔", "幽閣獨夜清琴曲：雍容華貴", "客舍青青柳色新：春光無限"], "a": 1, "e": "考點：植物象徵。\n(B) 歲寒知松柏之後凋：堅毅不拔、堅貞 → 正確。\n(A) 竹子中空 → 虛心，不是青春永駐。\n(C) 幽閣、清琴 → 蘭或幽雅，不是雍容華貴（牡丹）。\n(D) 客舍青青柳色新（王維〈送元二使安西〉）→ 柳象徵離別。\n★ 竹＝虛心；松柏＝堅貞；柳＝離別。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-115", "no": "115", "c": "k5", "src": "翰林 C卷・第5回 第 13 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "「香遠益清，亭亭淨植，可遠觀而不可褻玩焉。」意指君子高潔的品格，久而令人敬重，不敢加以輕慢戲弄。此與下列何者的涵義最相近？", "o": ["世上沒有輕輕事，一切都是得來不易的", "一個人能改正從前的錯誤，就能不斷地進步", "世界不給他歡樂，他卻創造了歡樂給世界", "一個人先看得起自己，別人才看得起他"], "a": 3, "e": "考點：文意對應。\n君子品格高潔，令人敬重、不敢輕慢 → 先自重，別人才會尊重 → (D) 一個人先看得起自己，別人才看得起他。\n★ 和第 85 題同一類：人必自重而後人重之。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-116", "no": "116", "c": "k6", "src": "翰林 C卷・第5回 第 14 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "愛蓮說一文末：「牡丹之愛，宜乎眾矣！」由這句話可以看出作者有何特質？", "o": ["與世浮沉，同流合汙", "謙懷溫厚，潔身自愛", "面面俱到，見風轉舵", "盛氣凌人，桀驁不馴"], "a": 1, "e": "考點：從語氣看作者特質。\n作者對愛牡丹的世人只有委婉的貶責，不嚴厲批評，態度溫厚；自己又獨愛蓮、潔身自愛 → (B) 謙懷溫厚，潔身自愛。\n(A)(C) 是與世浮沉；(D) 盛氣凌人，都不對。\n★ 和第 22 題同一類：委婉＝溫厚。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-117", "no": "117", "c": "k6", "src": "翰林 C卷・第5回 第 15 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "愛蓮說一文中作者對於三種人品的評論，何者正確？", "o": ["對於追求富貴者，嚴厲批評", "對於君子者，認為人數愈來愈多", "對於真正隱居者，認為人數極少", "對志同道合者，深表讚賞"], "a": 2, "e": "考點：作者對三種人的評論。\n(C) 正確：「菊之愛，陶後鮮有聞」→ 真正隱居的人極少。\n(A) 錯：對富貴者是「委婉」貶責，不是嚴厲批評。\n(B) 錯：君子愈來愈少（同予者何人）。\n(D) 錯：作者是感嘆找不到志同道合的人。\n★ 鮮有聞＝很少聽說。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-118", "no": "118", "c": "k11", "src": "翰林 C卷・第5回 第 16 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "「周敦頤胸懷坦蕩，立身處世如□□□□。愛蓮說一文把蓮花的美好，表達得□□□□。」空格處依序填入下列何者最適當？", "o": ["海晏河清／天馬行空", "冰壺秋月／淋漓盡致", "閒雲野鶴／躍然紙上", "春蘭秋菊／鞭辟入裡"], "a": 1, "e": "考點：詞語填空。\n胸懷坦蕩 → 冰壺秋月（比喻人品清白、心地光明）；表達得 → 淋漓盡致（完整透徹）→ (B)。\n(A) 海晏河清：天下太平；天馬行空：想法奔放。\n(C) 閒雲野鶴：無拘無束；躍然紙上：描寫生動。\n(D) 春蘭秋菊：各有所長；鞭辟入裡：分析透徹。\n★ 冰壺秋月＝人品光明磊落。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-119", "no": "119", "c": "k11", "src": "翰林 C卷・第5回 第 17 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "「百花發時我不發，我若發時都嚇殺。要與□風戰一場，遍身穿就黃金甲。」（朱元璋）請問缺空處應填入下列何字？", "o": ["東", "西", "南", "北"], "a": 1, "e": "考點：詠菊詩（朱元璋〈詠菊〉）。\n菊花在秋天開放，秋天吹「西」風（五行中秋屬西方），金黃的花瓣像穿上黃金甲 → (B) 西。\n★ 東風＝春；西風＝秋；北風＝冬。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-120", "no": "120", "c": "k10", "src": "翰林 C卷・第5回 第 18 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "象徵修辭是以具體的意象表達抽象的情感，例如以「背影」象徵「父愛」。下列「　」中的字詞所象徵的涵義，何者說明錯誤？", "o": ["「紅豆」生南國，春來發幾枝：相思", "人生非寒「松」，年貌豈長在：長壽", "採「菊」東籬下，悠然見南山：高潔隱士", "誰言「寸草」心，報得三春暉：母愛"], "a": 3, "e": "考點：象徵修辭。\n(D) 錯：「寸草心」象徵子女的孝心，「三春暉」才象徵母愛（孟郊〈遊子吟〉）。\n(A) 紅豆＝相思；(B) 寒松＝長青長壽；(C) 菊＝高潔隱士 → 正確。\n★ 寸草＝子女；三春暉＝母愛。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-121", "no": "121", "c": "k6", "src": "翰林 C卷・第5回 第 19 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "「落盡殘紅始吐芳，佳名喚作百花王。」（皮日休）請問此花象徵哪一種人？", "o": ["君子", "隱士", "平民百姓", "富貴人家"], "a": 3, "e": "考點：花的象徵。\n「百花王」→ 牡丹，象徵富貴 → (D) 富貴人家。\n★ 牡丹＝花王＝富貴。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-122", "no": "122", "c": "k5", "src": "翰林 C卷・第5回 第 20 題", "st": "考卷", "pk": "hc-5", "pname": "翰林 C卷・第5回（第四課）", "pord": 2, "ctx": "", "fig": "", "q": "「本無塵土氣，自在水雲鄉。楚楚淨如拭，亭亭生妙香。」（鄭允端詠蓮）詩中「楚楚淨如拭，亭亭生妙香」這句所描述蓮的特質與下列何者相似？", "o": ["中通外直，不蔓不枝", "出淤泥而不染", "可遠觀而不可褻玩焉", "香遠益清，亭亭淨植"], "a": 3, "e": "考點：詠蓮詩對應課文。\n「楚楚淨如拭」（潔淨）、「亭亭生妙香」（挺立、有香氣）→ (D) 香遠益清，亭亭淨植。\n★ 抓關鍵字：亭亭、香。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-123", "no": "123", "c": "k12", "src": "金安 B卷・第5次練習 第 1 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "下列文句，何者用字最為精簡？", "o": ["如果現在不努力學習，將來肯定後悔", "做人要腳踏實地，不然否則將得一場糊塗", "花了一個下午的時間，我總算將把模型拼好了", "阿銘整天無所事事，對於人生沒有任何毫無規劃"], "a": 0, "e": "考點：用字精簡。\n(A) 沒有贅字，最精簡。\n(B) 「不然」「否則」重複。\n(C) 「將」「把」重複（將＝把）。\n(D) 「沒有任何」「毫無」重複。\n★ 和第 36 題同一類：找意思重複的詞。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-124", "no": "124", "c": "k8", "src": "金安 B卷・第5次練習 第 2 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "下列「　」中的字，何組讀音前後相同？", "o": ["香遠「益」清／心胸狹「隘」", "「枝」葉扶疏／「伎」倆", "「宜」乎眾矣／友「誼」長存", "「濯」清漣而不妖／「拔」擢人才"], "a": 3, "e": "考點：形近字讀音。\n(D) 「濯」ㄓㄨㄛˊ／拔「擢」ㄓㄨㄛˊ → 相同。\n(A) 益ㄧˋ／隘ㄞˋ；(B) 枝ㄓ／伎ㄐㄧˋ；(C) 宜ㄧˊ／誼ㄧˋ。\n★ 第三次考濯、擢了，一定要記住ㄓㄨㄛˊ。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-125", "no": "125", "c": "k6", "src": "金安 B卷・第5次練習 第 3 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "「噫！菊之愛，陶後鮮有聞。蓮之愛，同予者何人？牡丹之愛，宜乎眾矣！」這段話應該如何解讀？", "o": ["感慨自己缺乏知己", "菊花、蓮花太過孤傲，不合時宜", "世人只知貪慕富貴，缺乏道德理想", "顯示牡丹的尊貴不凡，故人人追求之"], "a": 2, "e": "考點：末段三嘆的解讀。\n隱者少、君子更少、愛牡丹（追富貴）的人多 → (C) 世人只知貪慕富貴，缺乏道德理想。\n(A) 太狹隘；(B) 錯：作者肯定菊與蓮；(D) 錯：作者委婉貶責牡丹之愛。\n★ 和第 55 題同一類。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-126", "no": "126", "c": "k11", "src": "金安 B卷・第5次練習 第 4 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "(甲)蕙質蘭心　(乙)水性楊花　(丙)明日黃花　(丁)松柏後凋　(戊)胸有成竹　(己)紅杏出牆。以上與植物有關的成語，哪些屬於「貶義詞」？", "o": ["甲丙丁", "乙丙己", "乙戊己", "丙丁戊"], "a": 1, "e": "考點：植物成語的褒貶。\n(甲) 蕙質蘭心：女子聰慧高雅（褒）\n(乙) 水性楊花：女子用情不專（貶）\n(丙) 明日黃花：過時的事物（貶）\n(丁) 松柏後凋：堅貞（褒）\n(戊) 胸有成竹：事前已有把握（褒）\n(己) 紅杏出牆：女子不守婦道（貶）\n貶義為乙丙己 → (B)。\n★ 明日黃花＝過時（不是「昨日」黃花）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-127", "no": "127", "c": "k5", "src": "金安 B卷・第5次練習 第 5 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "愛蓮說以蓮花喻君子的德行，其中不包含何者？", "o": ["博施濟眾，仁民愛物", "鄙夷富貴，不同權勢", "潔身自好，不隨流俗", "高風亮節，清譽遠播"], "a": 0, "e": "考點：蓮花象徵的君子之德。\n(A) 博施濟眾、仁民愛物：文中沒有 → 不包含。\n★ 第三次考同一題（第 50、88 題），答案都是「博施濟眾」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-128", "no": "128", "c": "k8", "src": "金安 B卷・第5次練習 第 6 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "下列「　」中的字，何組字形前後相同？", "o": ["「ㄆㄢ」登懸崖／齊天「ㄆㄢ」", "不「ㄇㄢˋ」不枝／「ㄇㄢˋ」不經心", "正直清「ㄍㄨㄟ」／禮義「ㄍㄨㄟ」恥", "不可「ㄒㄧㄝˋ」玩焉／不「ㄒㄧㄝˋ」一顧"], "a": 1, "e": "考點：同音字辨形。\n教用答案為 (B)，但依目前文字：不「蔓」不枝／「漫」不經心，字形並不相同；本題選項轉檔時有誤，請對照原卷第 5-1 頁。\n(D) 不可「褻」玩／不「屑」一顧 → 不同。\n★ 蔓（草字頭，植物）≠ 漫（水字旁，隨便）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "B"}, {"id": "c4-129", "no": "129", "c": "k9", "src": "金安 B卷・第5次練習 第 7 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "下列字詞的詞性說明，何者正確？", "o": ["宜乎眾「矣」：介詞", "陶後「鮮」有聞：名詞", "香遠「益」清：動詞", "「噫」！菊之愛：助詞"], "a": 0, "e": "考點：詞性判斷。\n依課文：「矣」是句末語氣詞（助詞）；「鮮」是副詞（少）；「益」是副詞（更加）；「噫」是嘆詞。\n教用答案為 (A)，但目前選項文字與課文用法對不上（轉檔可能有誤），請對照原卷第 5-1 頁。\n★ 噫＝嘆詞；矣、焉、乎＝語氣助詞。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "題目", "orig": "A"}, {"id": "c4-130", "no": "130", "c": "k5", "src": "金安 B卷・第5次練習 第 8 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "阿翔為了飛上主管之職，整天向老闆諂媚吟態，不惜為其栽高帽，實在令人不齒。根據愛蓮說一文，阿翔的人格與何者違背？", "o": ["不蔓不枝", "濯清漣而不妖", "香遠益清", "出淤泥而不染"], "a": 1, "e": "考點：諂媚違背哪一德。\n諂媚逢迎、為老闆戴高帽 → 違背 (B) 濯清漣而不妖（不媚俗、不逢迎）。\n★ 和第 69、93 題同一類。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-131", "no": "131", "c": "k12", "src": "金安 B卷・第5次練習 第 9 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "「君子如抱美玉而深藏不市，小人則以石為玉而又炫耀之。」由上述文句可知小人的特質為何？", "o": ["習慣指鹿為馬", "缺乏自知之明", "總是人云亦云", "向來是非不分"], "a": 1, "e": "考點：文意理解。\n君子擁有美玉卻深藏不賣；小人把石頭當成玉還四處炫耀 → 小人把沒價值的當寶貝，不了解自己 → (B) 缺乏自知之明。\n★ 以石為玉＝看不清自己。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-132", "no": "132", "c": "k12", "src": "金安 B卷・第5次練習 第 10 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "「沒有一朵蓮花能否定淤泥；沒有一個今天的果實能否定昨天的種子；沒有迷失的痛苦，哪有尋得的歡喜？」下列何者符合這段話的旨意？", "o": ["今日事，今日畢", "每天都有新的挑戰必須面對", "覆水難收，錯過的難再找回", "走過的每一個腳印都是人生的資產"], "a": 3, "e": "考點：文意理解。\n和第 65 題同一段文字：過去的淤泥、種子、迷失都有價值 → (D) 走過的每一個腳印都是人生的資產。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-133", "no": "133", "c": "k9", "src": "金安 B卷・第5次練習 第 11 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "「予獨愛蓮」中的「予」字，是第一人稱「我」的意思。下列「　」中，何者也代表第一人稱？", "o": ["「余」憶童稚時", "「爾」安敢輕吾射", "待「君」久不至，已去", "所謂「伊」人，在水一方"], "a": 0, "e": "考點：第一人稱代詞。\n(A) 「余」憶童稚時＝我（沈復〈兒時記趣〉）→ 第一人稱。\n(B) 爾＝你（第二人稱）；(C) 君＝您（第二人稱）；(D) 伊＝那個人（第三人稱）。\n★ 第一人稱：予、余、吾、我。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "c4-134", "no": "134", "c": "k5", "src": "金安 B卷・第5次練習 第 12 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "愛蓮說用蓮的特質描寫君子的特性，何者錯誤？", "o": ["出淤泥而不染：不同流合汙", "濯清漣而不妖：不妖媚惑眾", "中通外直，不蔓不枝：不趨炎附勢", "可遠觀而不可褻玩焉：人格高尚使人輕慢戲弄"], "a": 3, "e": "考點：蓮的特質與君子之德。\n(D) 錯：可遠觀而不可褻玩＝人格高尚，使人「不敢」輕慢戲弄，選項說成「使人輕慢戲弄」，意思相反。\n★ 注意選項少了「不敢」，意思就反了。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-135", "no": "135", "c": "k2", "src": "金安 B卷・第5次練習 第 13 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "下列關於幾位古代重要人物的敘述，何者不正確？", "o": ["李白詩風浪漫，被尊稱為「天上謫仙人」", "周敦頤獨愛如光風霽月，被奉為宋代理學之祖", "陶淵明愛蓮不受推，後人推他為隱逸詩人之宗", "王維能詩會畫，被譽為「詩中有畫，畫中有詩」"], "a": 2, "e": "考點：古代人物常識。\n(C) 錯：陶淵明愛的是「菊」，不是蓮；他被尊為「古今隱逸詩人之宗」。\n(A) 李白：詩仙、天上謫仙人；(B) 周敦頤：宋代理學之祖（黃庭堅稱他胸懷如光風霽月）；(D) 王維：詩中有畫，畫中有詩 → 正確。\n★ 陶淵明＝菊＝隱逸詩人之宗。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "c4-136", "no": "136", "c": "k12", "src": "金安 B卷・第5次練習 第 14 題", "st": "考卷", "pk": "jb-5", "pname": "金安 B卷・第5次練習", "pord": 3, "ctx": "", "fig": "", "q": "「春天／百花爭妍的時候／我看不到你的影子／夏日／那濃郁的季節／我們不曾喝你的花信／到了秋天，群芳都已消逝／你卻獨散清純／亭亭玉立在寒風裡／詩人愛你高潔的風度／我卻愛你那顆猜金的心／因為培植你的／不是和風暖陽／乃是凜冽的寒霜」上述文段歌詠時，應是在歌詠何物？", "o": ["松", "蘭", "梅", "菊"], "a": 3, "e": "考點：新詩所詠之物。\n春天、夏天都看不到；到了秋天群芳消逝，「你卻獨放清芬」，培植你的是「凜冽的寒霜」→ 秋天傲霜的 (D) 菊。\n梅花是冬天在雪中開。\n★ 秋＋霜 → 菊；冬＋雪 → 梅。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-137", "no": "137", "c": "k9", "src": "翰林 A卷・第8回 第 1 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（第四～六課、語二）", "pord": 4, "ctx": "", "fig": "", "q": "下列各組「　」中的字，何組意思前後相同？", "o": ["牡丹「之」愛／花「之」君子", "多多「益」善／香遠「益」清", "窮鄉「僻」壤／冷「僻」字眼", "心情苦「悶」／天氣「悶」熱"], "a": 1, "e": "考點：一字多義。\n(B) 多多「益」善／香遠「益」清＝更加 → 相同。\n(A) 牡丹「之」愛：提賓助詞；花「之」君子：的。\n(C) 窮鄉「僻」壤：偏遠；冷「僻」：罕見。\n(D) 苦「悶」：心情煩悶；「悶」熱：不通風。\n★ 益＝更加。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-138", "no": "138", "c": "k5", "src": "翰林 A卷・第8回 第 2 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（第四～六課、語二）", "pord": 4, "ctx": "", "fig": "", "q": "下列文句，何者最適合用來形容蓮花「潔身自好，不隨同流合汙」的特性？", "o": ["中通外直，不蔓不枝", "蓮之愛，同予者何人", "香遠益清，亭亭淨植", "出淤泥而不染，濯清漣而不妖"], "a": 3, "e": "考點：一句對一德。\n「潔身自好，不同流合汙」→ (D) 出淤泥而不染，濯清漣而不妖。\n(A) 坦蕩正直、不攀附；(B) 感嘆知音少；(C) 美名遠播、端莊挺立。\n★ 出淤泥而不染＝不同流合污。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-139", "no": "139", "c": "k5", "src": "翰林 A卷・第8回 第 3 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（第四～六課、語二）", "pord": 4, "ctx": "", "fig": "", "q": "下列人物的行為與愛蓮說一文文句的配對何者正確？", "o": ["阿國品性端正、才德兼備，德風遠播，當時才學之士多來諮詢／濯清漣而不妖", "外公擔任公職，不但為人正派坦蕩，而且處事謹慎，頗得眾望／中通外直", "她雖出身豪門，但平日行事卻能謙恭節約，毫無驕奢媚世之態／出淤泥而不染", "雖然他的父母入獄服刑，哥哥也是個好閒，但他依然汲汲勵學／可遠觀而不可褻玩焉"], "a": 1, "e": "考點：人物行為與課文文句配對。\n(B) 為人正派坦蕩 → 中通外直，正確。\n(A) 德風遠播 → 應是「香遠益清」。\n(C) 謙恭節約、無驕奢媚世 → 應是「濯清漣而不妖」。\n(D) 家庭環境不好仍努力向學 → 應是「出淤泥而不染」。\n★ 先抓人物的關鍵特質，再找對應句。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-140", "no": "140", "c": "k10", "src": "翰林 A卷・第8回 第 4 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（第四～六課、語二）", "pord": 4, "ctx": "", "fig": "", "q": "下列何者與「蓮，花之君子者也」的句型相同？", "o": ["紅紅的小臉兒溫暖我的心窩", "詩必然是心靈的假期", "人生沒有永遠的順境", "夏夜的景色真是美麗極了"], "a": 1, "e": "考點：句型判斷。「蓮，花之君子者也」＝判斷句（A 是 B）。\n(B) 詩必然是心靈的假期 → 判斷句（A 是 B），相同。\n(A) 敘事句；(C) 有無句；(D) 表態句（形容詞當謂語）。\n★ 判斷句：「……是……」「……者，……也」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "c4-141", "no": "141", "c": "k6", "src": "翰林 A卷・第8回 第 5 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（第四～六課、語二）", "pord": 4, "ctx": "", "fig": "", "q": "在愛蓮說一文中，周敦頤感嘆：「蓮之愛，同予者何人？」其涵義為何？", "o": ["懷才不遇", "生不逢時", "愛花成痴", "知音難尋"], "a": 3, "e": "考點：「蓮之愛，同予者何人？」\n感嘆世上和自己一樣追求君子品德的人很少，找不到志同道合的人 → (D) 知音難尋。\n(A)(B) 文中沒有懷才不遇、生不逢時的意思。\n★ 同予者＝和我一樣的人。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "c4-142", "no": "142", "c": "k3", "src": "翰林 A卷・第8回 第 6 題", "st": "考卷", "pk": "ha-8", "pname": "翰林 A卷・第8回（第四～六課、語二）", "pord": 4, "ctx": "", "fig": "", "q": "下列四位同學對於文章內容的說明，何者正確？", "o": ["陸翰：愛蓮說藉物抒懷，闡述理想人格特質", "大鈞：生命的碎珠以平實筆調，夾敘夾議方式，強調交友的重要", "小安：鳥一文中多次使用視覺、視覺、嗅覺來摹寫鳥的美好", "阿寬：從愛蓮說一文可知周敦頤與陶淵明為好友，前者愛蓮，後者愛菊"], "a": 0, "e": "考點：課文綜合比較。\n(A) 正確：愛蓮說藉蓮抒懷，闡述君子的理想人格。\n(D) 錯：陶淵明是晉代人，周敦頤是北宋人，兩人相差六百多年，不可能是朋友。\n(B)(C) 是其他課文的說明，與題意不符（C 選項文字有重複，可能轉檔有誤）。\n★ 陶淵明（晉）、周敦頤（北宋）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}], "extras": [{"id": "text", "title": "課文與注釋", "html": "<h3>第一段　寫蓮（藉物言志）</h3><div class=\"vrt\"><p class=\"ktext\">水陸草木之花，可愛者甚<ruby>蕃<rt>ㄈㄢˊ</rt></ruby>。晉陶淵明獨愛菊；自李唐來，世人盛愛牡丹；<ruby>予<rt>ㄩˊ</rt></ruby>獨愛蓮之出淤泥而不染，<ruby>濯<rt>ㄓㄨㄛˊ</rt></ruby>清漣而不妖，中通外直，不蔓不枝，香遠益清，亭亭淨植，可遠觀而不可<ruby>褻<rt>ㄒㄧㄝˋ</rt></ruby>玩焉。</p><p class=\"note\"><b>注釋</b>　蕃：多，通「繁」。　李唐：唐朝，皇帝姓李。　盛：非常。　予：我。　淤泥：水底的汙泥。　濯：洗滌。　清漣：清澈而有微波的水。　妖：豔麗而不端莊。　中通外直：花梗中空，外形挺直。　不蔓不枝：不生藤蔓，不長枝節。　益：更加。　亭亭：高聳直立的樣子。　淨植：潔淨地挺立。　褻玩：輕慢地玩弄。</p><p class=\"note\"><b>語譯</b>　水上、陸地上各種草木的花，值得喜愛的非常多。晉朝陶淵明唯獨喜愛菊花；從唐朝以來，世人非常喜愛牡丹；我唯獨喜愛蓮花從汙泥中長出卻不被沾染，在清水中洗滌過卻不顯得妖媚，花梗中空外直，不生藤蔓也不長枝節，香氣傳得愈遠愈清幽，筆直潔淨地挺立著，只能遠遠地觀賞，卻不能輕慢地玩弄它。</p></div><h3>第二段　論花喻人（借花評人）</h3><div class=\"vrt\"><p class=\"ktext\">予謂菊，花之隱逸者也；牡丹，花之富貴者也；蓮，花之君子者也。<ruby>噫<rt>ㄧ</rt></ruby>！菊之愛，陶後<ruby>鮮<rt>ㄒㄧㄢˇ</rt></ruby>有聞；蓮之愛，同予者何人？牡丹之愛，宜乎眾矣！</p><p class=\"note\"><b>注釋</b>　謂：認為。　隱逸：隱居避世。　噫：嘆詞，表示感嘆。　菊之愛：愛菊，「之」為提賓助詞。　鮮：少。　同予者何人：和我一樣的有誰呢（激問，意思是沒有幾個人）。　宜乎：應當。　眾：多。</p><p class=\"note\"><b>語譯</b>　我認為菊花，是花中的隱士；牡丹，是花中的富貴者；蓮花，是花中的君子。唉！喜愛菊花的，陶淵明以後就很少聽說了；喜愛蓮花的，和我一樣的還有誰呢？喜愛牡丹的，應該很多了吧！</p></div>"}, {"id": "guoxue", "title": "國學常識", "html": "<h3>「說」體</h3><div class=\"vrt\"><p>「說」又稱<b>雜說</b>，是古代用來<b>解析事理、闡述己意</b>的文體，<b>盛行於唐、宋</b>。「說」偏重說明事理，「論」偏重議論辨析，兩者性質相近，現代統稱為<b>論說文</b>。「說」常夾敘夾議、藉物寓意，篇幅簡短。代表作：韓愈〈馬說〉、周敦頤〈愛蓮說〉。</p></div><h3>作者　周敦頤</h3><div class=\"vrt\"><p>周敦頤，字<b>茂叔</b>，<b>北宋</b>道州營道人。晚年在廬山蓮花峰下築書堂，堂前溪水取故鄉溪名「濂溪」，世稱<b>濂溪先生</b>。為官清廉公正，黃庭堅稱讚他胸懷如<b>光風霽月</b>。思想融合儒、道、釋，開創宋代理學，被尊為<b>宋代理學之祖</b>；程顥、程頤都是他的學生。</p></div><h3>作者生平時間軸</h3><div class=\"tbl\"><table><thead><tr><th>年代／時期</th><th>歷史事件</th><th>重點與背景</th><th>出處依據</th></tr></thead><tbody><tr><td>北宋真宗天禧元年（西元1017年）</td><td>周敦頤出生</td><td>出生於湖南道州營道（今湖南省道縣），字茂叔，原名敦實（後避英宗舊名改敦頤）。</td><td>自修第95、115頁／講義第65頁</td></tr><tr><td>青年至中年任官時期</td><td>任多地地方官，平反冤獄</td><td>歷任分寧主簿、南安軍司理參軍、廣東轉運判官等，為官清正廉潔、執法如山，拒絕媚上阿諛。</td><td>自修第115頁／講義第65頁</td></tr><tr><td>晚年退隱講學時期</td><td>定居廬山，創立濂溪學派</td><td>晚年定居廬山蓮花峰下，因堂前有溪引自故鄉而名「濂溪」，開館講學。二程（程顥、程頤）受學於門下。</td><td>自修第94、115頁／講義第65頁</td></tr><tr><td>北宋神宗熙寧六年（西元1073年）</td><td>周敦頤卒</td><td>享年五十七歲。身後家無餘財，只有破爛箱子一隻，展現高潔清廉節操。</td><td>自修第95、115頁／講義第65頁</td></tr><tr><td>南宋至後世</td><td>追諡元公，確立理學宗師地位</td><td>思想融合《易經》、《中庸》與道佛思想，提出「主靜」、「無欲」，被尊為「宋代理學之祖」。</td><td>自修第94、95頁／講義第65頁</td></tr></tbody></table></div><h3>文中人物　陶淵明</h3><div class=\"vrt\"><p>陶淵明，<b>晉代</b>人，不為五斗米折腰，辭官歸隱田園，愛菊（採菊東籬下，悠然見南山），被尊為<b>古今隱逸詩人之宗</b>。文中以他的「菊」為<b>正襯</b>。注意：陶淵明（晉）與周敦頤（北宋）相差六百多年，兩人不可能是朋友。</p></div>"}, {"id": "zi", "title": "字音字形・字義", "html": "<h3>必考字音</h3><div class=\"tbl\"><table><thead><tr><th>字</th><th>讀音</th><th>課文用法</th><th>注意</th></tr></thead><tbody><tr><td>蕃</td><td>ㄈㄢˊ</td><td>可愛者甚蕃：多（通「繁」）</td><td>不讀ㄈㄢ</td></tr><tr><td>濯</td><td>ㄓㄨㄛˊ</td><td>濯清漣：洗滌</td><td>擢（拔擢）、濯濯（光禿）也讀ㄓㄨㄛˊ</td></tr><tr><td>褻</td><td>ㄒㄧㄝˋ</td><td>褻玩：輕慢地玩弄</td><td>形近字：褒ㄅㄠ</td></tr><tr><td>鮮</td><td>ㄒㄧㄢˇ</td><td>陶後鮮有聞：少</td><td>新鮮、屢見不鮮讀ㄒㄧㄢ</td></tr><tr><td>盛</td><td>ㄕㄥˋ</td><td>盛愛牡丹：非常</td><td>盛飯讀ㄔㄥˊ</td></tr><tr><td>予</td><td>ㄩˊ</td><td>予獨愛蓮：我</td><td>給予讀ㄩˇ</td></tr><tr><td>噫</td><td>ㄧ</td><td>噫！：嘆詞</td><td></td></tr><tr><td>蔓</td><td>ㄇㄢˋ</td><td>不蔓不枝：生出藤蔓</td><td>漫不經心是「漫」，字形不同</td></tr></tbody></table></div><h3>一字多義</h3><div class=\"tbl\"><table><thead><tr><th>字詞</th><th>讀音</th><th>課文中用法與字義</th><th>其他常見字義與例句（考題常客）</th><th>出處依據</th></tr></thead><tbody><tr><td>鮮</td><td>ㄒㄧㄢˇ</td><td>陶後「鮮」有聞：少（副詞）</td><td>屢見不「鮮」／「鮮」花：新鮮的（ㄒㄧㄢ）</td><td>自修第100頁</td></tr><tr><td>予</td><td>ㄩˊ</td><td>「予」獨愛蓮：我，同「余」（代詞）</td><td>上天「予」我／賜「予」：給予（ㄍㄟˇ，動詞）</td><td>講義第69頁、自修第100頁</td></tr><tr><td>盛</td><td>ㄕㄥˋ</td><td>世人「盛」愛牡丹：非常、極（副詞）</td><td>繁「盛」：旺盛；「盛」飯：裝填（ㄔㄥˊ，動詞）</td><td>講義第69頁、自修第100頁</td></tr><tr><td>益</td><td>ㄧˋ</td><td>香遠「益」清：更加（副詞）</td><td>延年「益」壽：增加（動詞）；「益」友：好處（名詞）</td><td>自修第100頁</td></tr><tr><td>宜</td><td>ㄧˊ</td><td>「宜」乎眾矣：應當（副詞）</td><td>「宜」室「宜」家：合適、相稱（形容詞／動詞）</td><td>講義第69頁、自修第101頁</td></tr></tbody></table></div><h3>「之」字用法</h3><div class=\"tbl\"><table><thead><tr><th>句子範例</th><th>「之」字詞性</th><th>意義與作用</th><th>出處依據</th></tr></thead><tbody><tr><td>水陸草木之花</td><td>助詞</td><td>「的」</td><td>講義第69頁、自修第99頁</td></tr><tr><td>予獨愛蓮之出淤泥而不染</td><td>助詞</td><td>無義，舒緩語氣／結構助詞</td><td>講義第69頁、自修第99頁</td></tr><tr><td>菊之愛／牡丹之愛／蓮之愛</td><td>助詞</td><td>無義，提賓助詞（倒裝句：愛菊、愛牡丹、愛蓮）</td><td>講義第69頁、自修第99、102頁</td></tr><tr><td>蓮，花之君子者也</td><td>助詞</td><td>「的」</td><td>講義第69頁</td></tr><tr><td>送孟浩然「之」廣陵（延伸）</td><td>動詞</td><td>往、到</td><td>講義第69頁</td></tr><tr><td>求「之」不得（延伸）</td><td>代詞</td><td>代替人、事、物（他／它）</td><td>講義第69頁</td></tr></tbody></table></div><h3>「而」字用法</h3><div class=\"tbl\"><table><thead><tr><th>課文句子</th><th>前後語義關係</th><th>「而」字詞義</th><th>試題判讀考點</th></tr></thead><tbody><tr><td>出淤泥而不染</td><td>轉折關係</td><td>卻、但是</td><td>必考重點（表前後對立反差）</td></tr><tr><td>濯清漣而不妖</td><td>轉折關係</td><td>卻、但是</td><td>必考重點（表前後對立反差）</td></tr><tr><td>學而時習之（延伸比較）</td><td>順接／並列關係</td><td>並且、而且</td><td>常考對照選項</td></tr><tr><td>人而無信，不知其可也（延伸）</td><td>假設關係</td><td>如果、若是</td><td>常考對照選項</td></tr></tbody></table></div><h3>形近字・同音字辨析</h3><div class=\"tbl\"><table><thead><tr><th>組別</th><th>辨析</th></tr></thead><tbody><tr><td>濯／擢</td><td>濯清漣（洗）、拔擢（提拔）——讀音相同ㄓㄨㄛˊ，字形不同</td></tr><tr><td>淤</td><td>淤泥、淤積、淤塞——字形相同</td></tr><tr><td>蔓／漫</td><td>不蔓不枝、荒煙蔓草（植物）；漫不經心、漫山遍野（水字旁）</td></tr><tr><td>褻／屑</td><td>褻玩、褻瀆（ㄒㄧㄝˋ）；不屑一顧（ㄒㄧㄝˋ）——同音不同字</td></tr><tr><td>宜／誼</td><td>宜乎眾矣、權宜（ㄧˊ）；友誼、地主之誼（ㄧˋ）</td></tr><tr><td>纖</td><td>纖細、纖維——字形相同</td></tr></tbody></table></div>"}, {"id": "xiuci", "title": "修辭與句型", "html": "<h3>托物言志</h3><div class=\"vrt\"><p>表面寫花，實際寫人。作者藉蓮花的生長環境、形態與香氣，寄託自己潔身自愛、不慕富貴的志向。蓮＝君子＝作者自己，三者融為一體。</p></div><h3>襯托：正襯與反襯</h3><div class=\"vrt\"><p>以<b>菊</b>為<b>正襯</b>（同樣高潔，但消極避世），以<b>牡丹</b>為<b>反襯</b>（追逐富貴，與蓮相反），襯托出主角<b>蓮</b>。詳寫蓮，略寫菊與牡丹，主從分明。</p></div><h3>譬喻・排比・類疊</h3><div class=\"vrt\"><p>「菊，花之隱逸者也；牡丹，花之富貴者也；蓮，花之君子者也。」</p><p>把花比作人 → <b>譬喻</b>（暗喻，A，B 也）；三句結構相同 → <b>排比</b>；「花之……者也」重複 → <b>類疊</b>。注意：這一句沒有「倒反」。</p></div><h3>映襯</h3><div class=\"vrt\"><p>「菊之愛，陶後鮮有聞；蓮之愛，同予者何人？牡丹之愛，宜乎眾矣！」把喜愛人數少與多的對照放在一起，凸顯君子之少、追富貴者之多。</p></div><h3>激問</h3><div class=\"vrt\"><p>「蓮之愛，同予者何人？」答案在問題的反面——和我一樣的人<b>沒有幾個</b>。比較：「問君何能爾？心遠地自偏」是自問自答的<b>提問</b>。</p></div><h3>倒裝：賓語提前</h3><div class=\"vrt\"><p>菊之愛＝愛菊；牡丹之愛＝愛牡丹；蓮之愛＝愛蓮。「之」是<b>提賓助詞</b>，沒有意思。</p><p>同類句型：唯利是圖（唯圖利）、馬首是瞻（唯瞻馬首）、唯命是從（唯從命）、父母唯其疾之憂（唯憂其疾）、何難之有（有何難）。</p></div><h3>委婉貶責</h3><div class=\"vrt\"><p>「牡丹之愛，宜乎眾矣！」話說得客氣，其實是批評世人追逐富貴。作者不嚴厲責罵，態度溫厚——君子責人也輕以約。</p></div><h3>判斷句</h3><div class=\"vrt\"><p>「蓮，花之君子者也」＝蓮是花中的君子，屬於「A，B 也」的判斷句。白話的「A 是 B」也是判斷句，如「詩必然是心靈的假期」。</p></div>"}, {"id": "compare", "title": "易混淆比較", "html": "<h3>菊、牡丹、蓮三花比較</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>菊（正襯）</th><th>牡丹（反襯）</th><th>蓮（主體）</th></tr></thead><tbody><tr><td>花之美譽／人格化身</td><td>花之隱逸者也</td><td>花之富貴者也</td><td>花之君子者也</td></tr><tr><td>生長季節／外觀意象</td><td>秋季獨放、傲霜不屈</td><td>繁丹艷麗、雍容華貴</td><td>潔淨芬芳、端莊挺直</td></tr><tr><td>處世哲學與人生態度</td><td>出世，消極避世、潔身自好、獨善其身</td><td>隨俗，追逐名利、貪慕榮華、隨波逐流</td><td>入世，立足濁世卻潔身自愛、兼善天下</td></tr><tr><td>代表人物／崇尚族群</td><td>晉代 陶淵明</td><td>唐代以來 世俗大眾</td><td>周敦頤（自況）與少數抱道君子</td></tr><tr><td>在文中的烘托角色</td><td>正襯（陪襯），以高潔品格烘托蓮花</td><td>反襯，以世俗貪婪對照凸顯蓮花之卓絕</td><td>主角核心（立意主體）</td></tr><tr><td>末段作者態度與語氣</td><td>惋惜、肯定（「陶後鮮有聞」）</td><td>委婉諷刺、嗤之以鼻（「宜乎眾矣」）</td><td>感慨孤芳自持、求道同者極稀（「同予者何人」）</td></tr></tbody></table></div><h3>蓮花七德對照表</h3><div class=\"tbl\"><table><thead><tr><th>* <b>出處</b>：自修第104頁應用練習、講義第71頁應用練習</th><th></th></tr></thead><tbody><tr><td>* <b>要看懂什麼</b>：理解古人如何藉由自然界植物的客觀生長與外觀特徵，映射出儒家理想的君子德行</td><td></td><td>。</td></tr><tr><td>觀察面向</td><td>課文蓮花特徵描寫</td><td>象徵君子之德（對應美德）</td><td>試題常見意旨詮釋</td></tr><tr><td>生長環境</td><td>出淤泥而不染</td><td>潔身自愛，不同流合污</td><td>處在惡劣濁俗環境中，仍保持純潔本性</td></tr><tr><td>生長環境</td><td>濯清漣而不妖</td><td>節操高雅，不逢迎諂媚</td><td>不媚俗取巧，不以妖艷巧言迎合他人</td></tr><tr><td>花梗內部</td><td>中通</td><td>胸懷坦蕩，通達事理</td><td>內心光明虛懷，無私心雜念</td></tr><tr><td>花梗外觀</td><td>外直</td><td>行為正直，堅守原則</td><td>處事公正無私，剛正不阿</td></tr><tr><td>花梗旁枝</td><td>不蔓不枝</td><td>不攀附權貴，不結黨營私</td><td>立身端莊，不拉幫結派、不趨炎附勢</td></tr><tr><td>香氣特性</td><td>香遠益清</td><td>品格高潔，美名遠播</td><td>道德涵養醇美深遠，德澤流芳愈遠愈清</td></tr><tr><td>整體給人感受</td><td>亭亭淨植</td><td>獨立挺拔，卓爾不群</td><td>姿態端莊整肅，高潔直立</td></tr><tr><td>觀賞感受</td><td>可遠觀而不可褻玩焉</td><td>端莊嚴肅，令人敬仰而不敢輕慢戲弄</td><td>具備人格尊嚴，自重而後人重之</td></tr><tr><td>* <b>常見判讀方式</b>：連連看或填空題型，題目常給予現實生活中的行為情境（如：「立法院內不拉幫結派」對應「不蔓不枝」；「不隨黑心廠商造假」對應「出淤泥而不染」；「拒絕走後門關說」對應「外直」等）</td><td></td><td></td><td></td><td>。</td></tr></tbody></table></div><h3>「說」與「論」</h3><div class=\"tbl\"><table><thead><tr><th>比較面向</th><th>「說」（如《愛蓮說》、《馬說》）</th><th>「論」（如《六國論》）</th></tr></thead><tbody><tr><td>文體定位</td><td>亦稱雜說，偏重在「說明事理」、闡述己意</td><td>專門論述政見或歷史，偏重於「議論辨析」</td></tr><tr><td>行文風格</td><td>手法活潑多樣，常寄託主觀志向情懷、藉物發揮</td><td>結構嚴謹，以嚴密的論點、論據、論證為主體</td></tr><tr><td>共同歸類</td><td>兩者性質相近，古代常通用，現代文學體裁統稱為「論說文」</td></tr></tbody></table></div><h3>延伸圖表：青少年品格需求調查</h3><p>自修第106頁、講義第72頁：家長最重視孩子培養的品格，第一名是<b>自律精神</b>（56.88%），其次是<b>同理心</b>（44.51%）與<b>思考判斷力</b>（36.44%）。考題常結合論語名句（如「君子求諸己，小人求諸人」對應自律）一起考。</p>"}, {"id": "flow", "title": "行文脈絡", "html": "<h3>起　總提花之眾多</h3><div class=\"vrt\"><p>「水陸草木之花，可愛者甚蕃。」開頭點出各種花都有人喜愛，引出主題。</p></div><h3>承　分敘愛花傳統</h3><div class=\"vrt\"><p>晉陶淵明獨愛菊（正襯）；李唐以來世人盛愛牡丹（反襯）。表面依時間順序，實際鋪陳世俗與獨特兩種價值。</p></div><h3>轉　予獨愛蓮</h3><div class=\"vrt\"><p>詳寫蓮：生長環境（出淤泥而不染、濯清漣而不妖）→ 形態（中通外直、不蔓不枝）→ 香氣（香遠益清）→ 整體姿態（亭亭淨植、可遠觀而不可褻玩焉）。以形寫神，具體寫出君子人格。</p></div><h3>合　論花喻人，末段三嘆</h3><div class=\"vrt\"><p>第二段把花人格化：菊是隱逸者，牡丹是富貴者，蓮是君子。</p><p>末段三嘆：菊之愛，陶後鮮有聞（肯定、惋惜）；蓮之愛，同予者何人（感慨知音少）；牡丹之愛，宜乎眾矣（委婉諷刺）。</p></div><h3>結構一句話</h3><div class=\"vrt\"><p>第一段寫花（藉物言志），第二段寫人（借花喻人）。蓮是主體，菊是正襯，牡丹是反襯。</p></div>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>易錯點</h3><div class=\"vrt\"><p>陶後「鮮」有聞讀ㄒㄧㄢˇ，是「少」；屢見不鮮讀ㄒㄧㄢ。</p><p>菊之愛的「之」是提賓助詞，不是「的」。</p><p>宜乎眾矣是委婉諷刺，作者並不愛牡丹。</p><p>菊＝出世、獨善其身；蓮＝入世、兼善天下。</p><p>可遠觀而不可褻玩＝令人「不敢」輕慢，選項少了「不敢」就錯。</p><p>蓮的七德都是個人修養，<b>沒有</b>「博施濟眾，仁民愛物」。</p><p>課文<b>沒有</b>寫蓮花的顏色。</p></div><h3>蓮花七德口訣</h3><div class=\"vrt\"><p class=\"poem\">淤泥不染潔自愛，清漣不妖不諂態；<br>中通坦蕩外正直，不蔓不枝朋黨害；<br>香遠清幽美名在，亭亭淨植儀態泰；<br>遠觀可敬不可褻，君子尊嚴人自愛！</p></div><h3>三花人格口訣</h3><div class=\"vrt\"><p class=\"poem\">陶潛愛菊隱逸士，世人牡丹慕富貴；<br>獨愛蓮花為君子，出淤不染入世粹。</p></div><h3>人與花木配對</h3><div class=\"vrt\"><p>菊—陶淵明、蓮—周敦頤、梅—林逋、蘭—屈原、竹—蘇軾、鵝—王羲之、茶—陸羽、荔枝—楊貴妃。</p></div>"}]});
